/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
'use strict';
const D=globalThis.RA.D;
const Q=(w,n,s,p,o,k,x)=>({id:`${w}.q${n}`,senseId:`${w}.s${s}`,errorType:'meaning',type:'辨义与用法',prompt:p,options:o,answer:o[k],explain:x});
const C=(w,s,d,en,zh,st,g,r)=>({senseId:`${w}.s${s}`,domain:d,en,zh,structure:st,grammar:g,rationale:r,sourceType:'authored'});
const M=(wrong,right,reason)=>({errorType:'meaning',wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline, https://www.etymonline.com/word/${w.toLowerCase()}`});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:[C(w,...c)],mistakes:[M(...m)],quiz:qs.map((q,i)=>Q(w,i+1,q[0],q[1],q[2],q[3],q[4]))});
P('exhort','源于拉丁语 exhortari“鼓励、激励”，经法语进入英语，现常指郑重劝人采取行动。',[1,'公共服务','Before the storm, the mayor exhorted residents in low-lying streets to move to the shelters and take essential medicine with them.','暴风雨来临前，市长恳切劝告低洼街区居民前往避难所，并带上必需药物。','Before the storm, the mayor exhorted residents / in low-lying streets to move to the shelters / and take essential medicine with them.','及物动词；常接人作宾语，再接 to do，语气较正式而有力。','明确敦促居民撤离体现 exhort 的“恳切劝告”义。'],['The doctor exhorted the patient to ignore the warning signs and delay emergency care.','The doctor urged the patient to heed the warning signs and seek emergency care.','劝人忽略警讯与 exhort 的积极敦促相悖；改成 heed 和 seek emergency care。'],[[1,'To exhort a team to keep going is to?',['strongly urge them to continue','quietly record their names','order them to stop immediately'],0,'exhort 表示有力劝告、敦促某人行动。'],[1,'Which construction is standard?',['exhort someone to act','exhort someone at acting','exhort someone for act'],0,'exhort 后常接宾语和不定式。'],[1,'A coach exhorts the players before a final. The coach likely?',['gives them an earnest call to action','lists the final score from last year','asks them to abandon the match'],0,'赛前激励队员行动符合 exhort。'],[1,'Choose the closest meaning of “She exhorted them to vote.”',['She urged them to vote.','She prevented them from voting.','She counted their votes.'],0,'exhorted them to vote 即恳切敦促他们投票。']]);
P('exhume','经古法语 exhumer 进入英语，由 ex-“出”与拉丁语 humus“土”构成；既可指掘出遗体，也可比喻翻出旧事。',[1,'考古调查','With the family’s consent and a court order, investigators exhumed the grave to identify the remains using modern DNA testing.','在家属同意并取得法院命令后，调查人员掘开坟墓，通过现代 DNA 检测辨认遗骸。','With the family’s consent and a court order, / investigators exhumed the grave / to identify the remains using modern DNA testing.','及物动词；常以 buried body、remains 或 grave 为宾语；比喻义可接旧档案或往事。','句中对墓葬进行挖掘以取出遗骸，直接对应 s1。'],['The archive team exhumed the letter by burying it beneath the newly paved courtyard.','The archive team retrieved the letter from storage without damaging it.','把信埋入地下是 bury；exhume 在字面义中是从地下掘出。'],[[1,'Investigators exhume a body when they?',['dig it up from a grave','place it in a new grave','identify it without opening the grave'],0,'exhume s1 指从地下掘出遗体。'],[2,'A journalist “exhumed an old scandal” by?',['bringing a forgotten affair back into public view','burying all relevant records','proving the story never existed'],0,'比喻义 s2 是重新翻出被遗忘的丑闻。'],[1,'Which action is an example of literal exhumation?',['removing buried remains for examination','lowering a coffin into the earth','reading a recent newspaper aloud'],0,'从墓中取出遗骸是字面上的 exhume。'],[2,'Choose the closest paraphrase: “The inquiry exhumed the issue.”',['It brought the forgotten issue up again.','It permanently settled the issue.','It hid the issue from investigators.'],0,'比喻用法表示把旧问题重新带回关注。']]);
P('existent','由 exist 加形容词后缀 -ent 构成；exist 经中古法语源自拉丁语 existere“出现、存在”。',[1,'哲学讨论','The report separates existent evidence from predictions, so readers can see which findings have already been observed and which remain hypothetical.','报告把现存证据与预测分开，让读者看清哪些发现已被观察到，哪些仍是假设。','The report separates existent evidence from predictions, / so readers can see which findings have already been observed / and which remain hypothetical.','形容词，意为实际存在的；existent 较正式，常用于哲学或论证语境。','已被观察到的证据与假设相对，说明 existent 的“实际存在”义。'],['The nonexistent island was existent on no map because it had been imagined by the novelist.','The island existed only in the novelist’s imagination and was not real.','虚构岛屿并非实际存在，称 nonexistent 才符合句意。'],[[1,'An existent problem is one that?',['actually exists now','might be invented next year','has already been solved and removed'],0,'existent 指现实中存在的。'],[1,'Which contrasts existent evidence with a proposal?',['observed evidence versus an idea not yet realised','two spellings of the same word','a fact versus a different fact'],0,'existent 指已实际存在，与尚未实现的计划相对。'],[1,'If a danger is existent, it is?',['real rather than merely imagined','certain to appear only in the future','impossible to observe'],0,'该形容词强调现实存在。'],[1,'Choose the natural phrase.',['existent conditions','existent to walk','existent more carefully'],0,'existent 是修饰名词的形容词。']]);
P('existing','由 exist 加 -ing 形成的形容词，表示已经存在或当前采用的；词根经拉丁语 existere“出现、存在”传入英语。',[1,'城市规划','Rather than demolish the existing footbridge, the council will reinforce its supports and add a ramp for wheelchair users.','市议会将加固现有步行桥的支撑并增设轮椅坡道，而不是拆除它。','Rather than demolish the existing footbridge, / the council will reinforce its supports / and add a ramp for wheelchair users.','常置于名词前表示已经存在的设施、制度或状况；与 new、proposed 相对。','步行桥在改造之前就已存在，因此 existing 用得准确。'],['The city approved an existing bridge that has not yet been built and exists only as a proposal.','The city approved a proposed bridge that has not yet been built and exists only as a proposal.','尚未建成的桥是 proposed，不是 existing。'],[[1,'An existing rule is a rule that?',['is already in force','is only being considered','was cancelled before it began'],0,'existing 表示目前已经存在或实施。'],[1,'Which phrase contrasts new construction with current facilities?',['existing facilities','facilities that might exist someday','facilities already demolished'],0,'existing facilities 指现有设施。'],[1,'A company adapts an existing system instead of building another. The system?',['is already there','has never been created','will be invented later'],0,'existing 强调已经存在。'],[1,'Choose the natural collocation.',['existing customers','existing to discuss','existing more loudly'],0,'existing 可置于 customers 前作定语。']]);
P('exocrine','由希腊语 exō“向外”与 krinein“分泌”构成，医学形容词，描述经导管向体表或腔道排出产物的腺体。',[1,'生理学','Unlike an endocrine gland, an exocrine gland releases its product through a duct; a sweat gland is a familiar example.','与内分泌腺不同，外分泌腺通过导管释放产物；汗腺就是常见例子。','Unlike an endocrine gland, an exocrine gland releases its product through a duct; / a sweat gland is a familiar example.','医学形容词；常和 gland 连用；区分点是有导管向外排出分泌物。','汗腺经导管把汗液排到皮肤表面，符合 exocrine。'],['The textbook called the ductless thyroid exocrine because it releases hormones directly into blood.','The textbook called the ductless thyroid endocrine because it releases hormones directly into blood.','无导管并直接入血是内分泌特征，不能称 exocrine。'],[[1,'An exocrine gland sends its product?',['through a duct toward a surface or cavity','directly into blood without a duct','only into the cell nucleus'],0,'exocrine 的判别特征是分泌物经导管排出。'],[1,'Which is a familiar exocrine gland?',['a sweat gland with ducts to the skin','a ductless gland releasing hormones to blood','a bone that stores minerals'],0,'汗腺通过导管排汗，属外分泌腺。'],[1,'The prefix exo- in exocrine indicates?',['outward','inside','before'],0,'exo- 源自表示“向外”的希腊语成分。'],[1,'Choose the biologically accurate statement.',['Exocrine secretion travels through a duct.','Exocrine secretion must enter the bloodstream directly.','Exocrine describes a gland with no secretory product.'],0,'通过导管排出的分泌属于外分泌。']]);
P('exodus','源自希腊语 exodos“离开、出口”，经拉丁语与圣经传统进入英语，常指大批人同时离去。',[1,'人口迁移','After the factory closed, an exodus of young workers left the town for cities where they could find new jobs.','工厂关闭后，大批年轻工人离开小镇，前往能找到新工作的城市。','After the factory closed, / an exodus of young workers left the town / for cities where they could find new jobs.','可数名词；常用 an exodus of people/workers/refugees；强调集体、大规模离开。','许多工人同时离城构成 exodus，而非个别离开。'],['A single tourist’s brief walk from the hotel was described as a mass exodus of the whole population.','The mass departure of residents after the flood was described as an exodus.','一个游客短暂外出不构成大批人离去；exodus 强调规模与集体性。'],[[1,'An exodus of residents means?',['a large number of residents leave','one resident arrives','residents return to their homes'],0,'exodus 指大批人离开。'],[1,'Which event is most clearly an exodus?',['thousands leave a region after conflict','one guest steps outside for a minute','a family moves furniture within a house'],0,'大量人口离开某地区符合 exodus。'],[1,'Choose the usual construction.',['an exodus of refugees','an exodus to persuade someone','exodus a large number of people'],0,'常见结构是 an exodus of + 人群。'],[1,'The word exodus emphasises?',['collective departure on a large scale','a routine daily arrival','a short private conversation'],0,'该词强调大规模集体离去。']]);
P('exogenous','由希腊语 exō“外部”与 -genēs“产生的”构成，指起因来自研究对象、系统或机体之外。',[1,'经济建模','The analyst treated the sudden oil-price shock as an exogenous factor because it originated outside the domestic model being studied.','分析员把油价骤变视为外生因素，因为它源自所研究的国内模型之外。','The analyst treated the sudden oil-price shock / as an exogenous factor / because it originated outside the domestic model being studied.','学术形容词；系统边界决定内外，常与 factor、variable、shock 连用。','油价冲击来自模型所研究的国内系统之外，故是 exogenous。'],['The analyst called a company’s internal staffing decision exogenous because the decision was made inside the company.','The analyst called a company’s internal staffing decision endogenous because it was made inside the company.','由系统内部产生应称 endogenous；exogenous 指外部来源。'],[[1,'An exogenous shock originates?',['outside the system being analysed','within the system itself','after the system has ended'],0,'exogenous 的关键是起源于研究系统之外。'],[1,'In a medical study, an exogenous substance comes from?',['outside the organism','the organism’s own cells only','a fictional source'],0,'生物学语境中 exogenous 指外源性的。'],[1,'Which variable is exogenous to a model of one firm?',['a tax change imposed by the government','the firm’s own output choice','a value calculated from its sales'],0,'外部政府政策不由企业模型内生决定。'],[1,'The prefix exo- means?',['outside or outward','equal','underneath'],0,'exo- 表示外部、向外。']]);
P('exorbitant','源自拉丁语 exorbitare“偏离轨道”，经法语进入英语，现表示价格、费用等高得不合理。',[1,'消费','The landlord demanded an exorbitant deposit equal to six months’ rent, so the tenants sought advice before signing.','房东要求支付相当于六个月租金的离谱押金，因此租客签约前先咨询了意见。','The landlord demanded an exorbitant deposit / equal to six months’ rent, / so the tenants sought advice before signing.','形容词，常修饰 price、fee、cost、demand；强调远超合理或公平范围。','六个月租金的押金远超正常水平，体现 exorbitant。'],['The shop charged an exorbitant price that was lower than every competing offer and well within the local average.','The shop charged a modest price that was lower than every competing offer and well within the local average.','低于同行且在平均范围内的价格并非高得离谱，modest 才吻合。'],[[1,'An exorbitant fee is?',['far higher than is reasonable','small and affordable','paid exactly on time'],0,'exorbitant 表示过分高昂。'],[1,'Which bill is most likely exorbitant?',['a routine repair costing ten times the quoted fair rate','a discounted bus ticket','a free public service'],0,'远高于合理报价的费用属于 exorbitant。'],[1,'Choose the natural collocation.',['exorbitant rent','exorbitant yesterday','exorbitant very carefully'],0,'exorbitant 常修饰 rent、price 等名词。'],[1,'If someone calls a price exorbitant, they judge it?',['unreasonably high','surprisingly low','impossible to calculate'],0,'这个词表达价格高得不合理。']]);
P('exoskeleton','由希腊语 exō“外部”与 skeletos“骨架”构成，指动物身体外侧坚硬的支撑和保护结构。',[1,'动物学','A beetle’s exoskeleton protects its softer tissues and gives muscles a firm surface against which to act.','甲虫的外骨骼保护柔软组织，也为肌肉活动提供坚固的支点。','A beetle’s exoskeleton protects its softer tissues / and gives muscles a firm surface / against which to act.','名词；节肢动物有外骨骼；不要与脊椎动物内部的 endoskeleton 混淆。','位于甲虫身体外侧并兼具保护和支撑功能，符合定义。'],['The biologist described a whale’s internal spine as an exoskeleton surrounding the animal.','The biologist described a crab’s hard outer covering as an exoskeleton.','鲸的脊柱位于体内，是内骨骼；螃蟹的硬外壳才是外骨骼。'],[[1,'An exoskeleton is located?',['on the outside of an animal’s body','only inside the skull','between two layers of cloud'],0,'exo- 表示外部，exoskeleton 位于身体外侧。'],[1,'A crab’s hard shell functions as?',['an external support and protective covering','a hollow internal bone','a breathing tube in its lungs'],0,'蟹壳属于外部支撑和保护结构。'],[1,'Which contrast is accurate?',['An exoskeleton is external; an endoskeleton is internal.','Both terms mean a soft outer skin.','An endoskeleton is always outside the body.'],0,'两词分别指外骨骼和内骨骼。'],[1,'Muscles can use an exoskeleton as?',['a firm point of attachment or leverage','a source of sunlight','a digestive enzyme'],0,'外骨骼为肌肉提供支撑和附着点。']]);
P('exothermic','由希腊语 exō“向外”与 thermos“热”构成，描述向周围释放热量的化学反应。',[1,'化学实验','The neutralisation reaction warmed the flask because it was exothermic and transferred heat from the reacting chemicals to the surroundings.','中和反应使烧瓶变暖，因为这是放热反应，热量从反应物传到周围环境。','The neutralisation reaction warmed the flask / because it was exothermic / and transferred heat from the reacting chemicals to the surroundings.','化学形容词，描述反应过程；热量流向环境。吸收热量的是 endothermic。','烧瓶变暖说明热量向外释放，符合 exothermic。'],['The ice bath cooled the reaction because it was exothermic and absorbed heat from its surroundings.','The ice bath cooled the reaction because it was endothermic and absorbed heat from its surroundings.','吸收周围热量是吸热 endothermic，不是 exothermic。'],[[1,'An exothermic reaction?',['releases heat to its surroundings','absorbs heat from its surroundings','does not involve energy transfer'],0,'exothermic 表示反应向外释放热量。'],[1,'Which observation suggests an exothermic process?',['the container becomes warmer without external heating','the reaction mixture cools as it absorbs heat','the thermometer is removed before measurement'],0,'放热会把能量传给周围，容器可能升温。'],[1,'The prefix exo- helps indicate heat moves?',['outward from the reacting system','into the reacting system','only sideways'],0,'exo- 表示向外，热量由系统向环境释放。'],[1,'Which is the opposite term?',['endothermic','isothermal','isotopic'],0,'endothermic 指吸热，与放热相对。']]);
P('expansionist','由 expansion 加 -ist 构成，表示支持领土、市场或政治控制扩大的主张，也可作名词指持此主张的人。',[1,'国际关系','The historian described the minister as expansionist because he repeatedly advocated annexing neighbouring territory and extending military control.','历史学家称这位部长奉行扩张主义，因为他一再主张吞并邻国领土并扩大军事控制。','The historian described the minister as expansionist / because he repeatedly advocated annexing neighbouring territory / and extending military control.','形容词义见 s1；名词义 s2 指支持扩张政策的人。常与 policy、power、leader 连用。','主张吞并邻国是扩张主义政策，体现 s1。'],['The expansionist government promised to surrender its territory and end all attempts to extend its influence.','The non-expansionist government promised not to extend its territory or influence.','放弃扩张不是 expansionist；non-expansionist 更符合该立场。'],[[1,'An expansionist policy aims to?',['extend territory or influence','give up all political control','reduce a state to local government'],0,'形容词 expansionist 指旨在扩大版图或影响力。'],[2,'An expansionist is a person who?',['supports political or territorial expansion','opposes every form of growth','studies the history of food'],0,'名词义指支持扩张的人。'],[1,'Which action is most clearly expansionist?',['a state annexes a neighbouring region','a state withdraws from a disputed region','a state limits its borders by treaty'],0,'吞并领土体现扩张主义。'],[1,'Choose the natural phrase.',['an expansionist foreign policy','an expansionist politely','expansionist of the meeting'],0,'expansionist 可作形容词修饰 policy。']]);
P('expansive','源自拉丁语 expandere“展开、扩张”，经法语进入英语；既可指宽广，也可指性格开朗健谈。',[2,'人物交流','Usually reserved in meetings, Dr. Chen became expansive over dinner, telling the new researchers stories about her early fieldwork.','陈博士平时开会较拘谨，晚餐时却开朗健谈，给新研究人员讲起早年的野外工作。','Usually reserved in meetings, / Dr. Chen became expansive over dinner, / telling the new researchers stories about her early fieldwork.','s1 指广阔或范围扩大的；s2 描述人谈兴浓、愿意畅谈。','晚餐时主动谈往事体现 s2，而非物理面积大。'],['The expansive guest answered every question with one-word replies and refused to join the conversation.','The reticent guest answered every question with one-word replies and refused to join the conversation.','沉默寡言与开朗健谈相反，reticent 才贴合。'],[[2,'An expansive host is likely to be?',['friendly and willing to talk at length','silent and unwilling to speak','physically very tall'],0,'expansive s2 描述开朗健谈的性格。'],[1,'An expansive view from a hill is?',['wide and far-reaching','narrow and blocked','heard rather than seen'],0,'expansive s1 可表示视野广阔。'],[2,'A normally quiet person becomes expansive at dinner. The person?',['talks freely and warmly','moves to a larger house','speaks only in writing'],0,'人的 expansive 可指谈得开、健谈。'],[1,'Which noun naturally follows expansive in the spatial sense?',['landscape','silence','deadline'],0,'expansive landscape 指广阔的景观。']]);
P('expansively','由 expansive 加副词后缀 -ly 构成，可描述空间广阔，也可描述说话开朗而详尽。',[1,'采访','When asked about the village school, the retired teacher spoke expansively about its students, describing their projects and later careers.','谈到村里的学校时，退休教师兴致勃勃地讲了许多学生的项目和后来的职业。','When asked about the village school, / the retired teacher spoke expansively about its students, / describing their projects and later careers.','副词；可描述空间开阔，也可表示畅谈、详尽地谈，这里为谈话义。','教师愿意详细讲述学生经历，体现“畅谈、详尽地谈”这一用法。'],['The spokesperson answered expansively with a single “No” and declined to offer any details.','The spokesperson answered tersely with a single “No” and declined to offer any details.','单字答复且拒绝展开属于简短 tersely，而非 expansively。'],[[1,'To speak expansively about a subject is to?',['talk about it freely and at length','refuse to mention it','speak only one word'],0,'expansively s2 表示畅谈、详尽地说。'],[1,'A garden is laid out expansively when it is arranged?',['across a broad area','inside a tiny closed box','only in alphabetical order'],0,'空间义表示布局开阔。'],[1,'Which reply is given expansively?',['a detailed, open account of the decision','a silent nod','a brief refusal to explain'],0,'充分详述并开放交流是 expansively 的谈话义。'],[1,'Choose the closest paraphrase: “She gestured expansively as she described the plan.”',['She spoke and gestured broadly, with room for detail.','She hid the plan from the listeners.','She gave an exact measurement of her hand.'],0,'此处表示表达开阔、详尽；不限定精确的面积测量。']]);
P('expectancy','由 expect 加名词后缀 -ancy 构成，表示期待某事发生的心理状态，也用于寿命预期等固定表达。',[1,'候诊室','In the waiting room, a tense expectancy settled over the families as the surgeon prepared to deliver the results.','外科医生准备公布结果时，候诊室里的家属陷入紧张的期待之中。','In the waiting room, / a tense expectancy settled over the families / as the surgeon prepared to deliver the results.','不可数名词，常与 sense/air of expectancy 连用；life expectancy 表示预期寿命。','家属等待重要消息时的心理状态体现 expectancy。'],['There was no expectancy in the room because everyone knew the result had already been announced and nothing remained to await.','There was little anticipation in the room because everyone knew the result had already been announced.','已公布结果且无需等待时，没有期待气氛；anticipation 表达等待发生的心理。'],[[1,'Expectancy is a feeling of?',['waiting for something expected to happen','regretting something that already happened','refusing to consider the future'],0,'expectancy 表示预期或期待的状态。'],[1,'A sense of expectancy before a result suggests people are?',['anticipating what will be announced','unaware that an announcement exists','celebrating a result from years ago'],0,'sense of expectancy 是事情将发生前的期待感。'],[1,'In “life expectancy,” expectancy refers to?',['the expected length of life','a person’s daily schedule','the cost of medical insurance'],0,'life expectancy 是预期寿命。'],[1,'Choose the usual phrase.',['an air of expectancy','expectancy into the room','expectancy to measure carefully'],0,'an air of expectancy 表示一种期待的氛围。']]);
P('expedient','源于拉丁语 expedire“使适用、使摆脱束缚”，经法语进入英语；作形容词指权宜有用，作名词指权宜办法。',[1,'危机决策','For the overnight repair, using a temporary bypass was expedient, though the engineer insisted it could not replace a permanent safety upgrade.','为连夜抢修，临时绕行管道是权宜之计，但工程师坚持它不能替代永久安全升级。','For the overnight repair, / using a temporary bypass was expedient, / though the engineer insisted it could not replace a permanent safety upgrade.','s1 为形容词“当下有用但未必理想”；s2 为名词“权宜办法”。有时含为方便而不顾原则之意。','临时方案有助于应急，但不能解决长久问题，符合 s1。'],['The manager rejected an expedient because the proposed shortcut was impossible to carry out before morning.','The manager adopted an expedient because the temporary shortcut could solve the immediate problem.','能立即解决问题的临时办法才是 expedient；不可执行的方案不具权宜价值。'],[[1,'An expedient solution is often?',['useful for the immediate aim, though not ideal','the only morally perfect choice','unrelated to the problem'],0,'expedient s1 指有助于达到当下目的的。'],[2,'A temporary workaround used to meet a deadline is an?',['expedient','expedition','explanation'],0,'名词 expedient 指权宜办法。'],[1,'Which choice may be expedient but not principled?',['taking a convenient shortcut that avoids a fair procedure','following a careful process despite the delay','refusing to act until all evidence is checked'],0,'expedient 有时暗含为图方便而牺牲原则。'],[2,'Choose the correct use: “The team adopted an expedient.” Here expedient is?',['a temporary means of achieving an aim','a person who predicts weather','a permanent legal office'],0,'冠词 an 显示这里 expedient 作名词。']]);
P('expedite','源于拉丁语 expedire“使摆脱障碍、使便利”，经法语进入英语，现常指加快流程或交付。',[1,'行政办理','To expedite the visa review, the applicant uploaded the missing medical certificate before the consulate’s daily processing deadline.','为加快签证审核，申请人在领事馆当天的处理截止时间前上传了缺失的医疗证明。','To expedite the visa review, / the applicant uploaded the missing medical certificate / before the consulate’s daily processing deadline.','及物动词，后接 procedure、delivery、review 等；表示促进加快，不等于批准。','补交材料旨在缩短审核流程，体现 expedite。'],['The extra forms expedited the application by ensuring that it could not be reviewed until next year.','The extra forms delayed the application by ensuring that it could not be reviewed until next year.','让审核推迟到明年是 delay，而不是 expedite。'],[[1,'To expedite a delivery is to?',['make it happen sooner','cancel it permanently','measure the package'],0,'expedite 表示加快交付。'],[1,'Which action could expedite a permit review?',['submit all required documents promptly','hide a required document','send the application to the wrong office'],0,'及时提交材料有助于加快审批。'],[1,'Does expedite necessarily mean “approve”?',['No; it means speed up the process.','Yes; every expedited request must be granted.','No; it means reject the request.'],0,'expedite 是加快办理，不保证结果获批。'],[1,'Choose the natural collocation.',['expedite the investigation','expedite at the investigation','expedite the investigation yesterdayly'],0,'expedite 是及物动词，可直接接 investigation。']]);
P('expeditious','由拉丁语 expedire“使便利、脱困”衍生，表示迅速且有效率地完成，不浪费时间。',[1,'客户服务','The claims office gave an expeditious response, resolving the straightforward cases that afternoon and assigning complex ones to specialists.','理赔部门回应迅速高效，当天下午处理了简单案件，并把复杂案件交给专家。','The claims office gave an expeditious response, / resolving the straightforward cases that afternoon / and assigning complex ones to specialists.','正式形容词，常修饰 response、manner、process；强调速度与效率兼具。','快速处理简单案件并合理分派复杂案件体现迅速而高效的处理。'],['The expeditious process took six months of avoidable delays and left every case untouched.','The protracted process took six months of avoidable delays and left every case untouched.','漫长且延误的流程并不迅速高效，protracted 才准确。'],[[1,'An expeditious reply is?',['quick and efficiently handled','slow despite being simple','careless and unrelated'],0,'expeditious 强调快且有效率。'],[1,'Which process is expeditious?',['a permit issued promptly after a complete review','a routine form left unread for months','a fast decision made without checking required facts'],0,'及时完成且经必要审核体现迅速高效。'],[1,'Expeditious differs from merely quick because it also suggests?',['efficiency and lack of wasted time','recklessness in every case','a large physical size'],0,'expeditious 不只快，也强调效率。'],[1,'Choose the natural phrase.',['an expeditious response','expeditious of the response','expeditious yesterday'],0,'expeditious 可修饰 response。']]);
P('expendable','由 expend“花费、消耗”加 -able 构成，表示在较大目标面前可以消耗或舍弃的。',[1,'安全管理','The safety plan treats the battery pack as expendable: if it overheats, workers can discard it rather than risk injury trying to save it.','安全方案把电池组视为可消耗品：若它过热，工人可以弃置，而不必冒受伤风险去抢救。','The safety plan treats the battery pack as expendable: / if it overheats, workers can discard it / rather than risk injury trying to save it.','形容词；可指用后即弃，也可指在更大目标下可牺牲；用于人的语境时可能显得冷酷。','过热电池可弃置以保障安全，体现“可舍弃”义。'],['The report called the only rescue boat expendable because its loss would make the evacuation impossible.','The report called the rescue boat indispensable because its loss would make the evacuation impossible.','救援不可或缺说明不能轻易舍弃，应称 indispensable。'],[[1,'An expendable component is one that?',['can be used up or discarded when needed','must be preserved at any cost','has no possible use'],0,'expendable 指可以消耗或舍弃。'],[1,'A disposable medical mask is often described as?',['expendable after use','irreplaceable for all future use','invisible to the wearer'],0,'一次性用品用后可丢弃，属于 expendable。'],[1,'Calling workers expendable may imply that management?',['treats their loss as acceptable for a larger goal','is committed to protecting each worker','cannot assign them any task'],0,'用于人的语境会暗示把人当作可牺牲的。'],[1,'Choose the closest meaning: “The parts are expendable.”',['The parts may be used up or replaced.','The parts cannot ever be replaced.','The parts are guaranteed to last forever.'],0,'expendable 表示可耗用或可替换。']]);
P('experimentation','由 experiment 加 -ation 构成，源自拉丁语 experimentum“试验”，指进行实验或反复尝试的过程。',[1,'研究方法','The laboratory’s experimentation over several months showed that humidity, rather than light, caused the coating to peel.','实验室数月的实验表明，导致涂层剥落的是湿度而非光线。','The laboratory’s experimentation over several months showed / that humidity, rather than light, / caused the coating to peel.','不可数名词；常指系统性实验过程或探索尝试，区别于一次具体 experiment。','持续数月的试验过程是 experimentation。'],['The team’s experimentation consisted of one untested guess, with no trial or observation at all.','The team’s speculation consisted of one untested guess, with no trial or observation at all.','没有实际试验的猜测是 speculation，不是 experimentation。'],[[1,'Experimentation refers most directly to?',['the process of carrying out experiments','a final published conclusion only','a person who buys laboratory glassware'],0,'experimentation 指实验活动或过程。'],[1,'Which sentence uses experimentation naturally?',['Further experimentation is needed to test the mixture.','An experimentation won the race yesterday.','She experimentation the sample carefully.'],0,'不可数的 experimentation 可作实验过程的名词。'],[1,'Experimentation differs from a single experiment because it often means?',['a broader or continuing process of trials','a guaranteed result before testing','a written biography'],0,'-ation 名词常表达活动或过程，范围可大于单次实验。'],[1,'What is required for genuine experimentation?',['trying a procedure and observing what happens','only imagining a result without testing','copying a conclusion without evidence'],0,'实验需进行试验并观察结果。']]);
P('experimenter','由 experiment 加施事后缀 -er 构成，指设计、实施或参与实验的人。',[1,'科学研究','The experimenter blinded the participants to the treatment groups and recorded the responses before checking the study code.','实验者让参与者不知道各自的处理组别，并在查看研究编码前记录反应。','The experimenter blinded the participants to the treatment groups / and recorded the responses / before checking the study code.','可数名词；指实验的实施者，不必然等同于研究负责人或受试者。','设计盲法并记录数据的人是 experimenter。'],['The experimenter was the chemical solution in the test tube, while the researcher simply observed it.','The experimental substance was the chemical solution in the test tube, while the researcher acted as the experimenter.','试剂是实验对象或材料，不是实施实验的人。'],[[1,'An experimenter is?',['someone who conducts or designs an experiment','a conclusion written before testing','a container that holds every sample'],0,'experimenter 指实验者。'],[1,'Which person is the experimenter in a lab study?',['the researcher who applies the procedure and records results','the microscope used to view cells','the untreated chemical alone'],0,'实施程序并记录结果的人是实验者。'],[1,'The suffix -er here most plausibly names?',['a person who performs an activity','a past event','a condition of being measured'],0,'-er 常构成施事者名词。'],[1,'A careful experimenter should?',['record observations systematically','change results to fit a preferred answer','skip the method and invent data'],0,'实验者需如实、系统记录观察结果。']]);
P('expertly','由 expert 加副词后缀 -ly 构成；expert 经法语源自拉丁语 expertus“经验证的”。',[1,'木工','Mara expertly cut the dovetail joints by checking each angle twice, leaving no visible gaps when the cabinet frame was assembled.','玛拉熟练地切出燕尾榫，并反复核对角度，柜架组装后看不出缝隙。','Mara expertly cut the dovetail joints / by checking each angle twice, / leaving no visible gaps when the cabinet frame was assembled.','副词，修饰动作，强调高度熟练或专业；常与 handle、perform、cut 等搭配。','反复测角并切出严密榫接体现专业熟练的操作。'],['The apprentice expertly joined the panels by leaving wide gaps at every corner and ignoring the measurements.','The apprentice poorly joined the panels by leaving wide gaps at every corner and ignoring the measurements.','粗心操作与 expertly 意义相反，poorly 才贴合语境。'],[[1,'If a technician handles a delicate repair expertly, the repair is done?',['with a high level of skill','without looking at the instructions or result','by accident with no control'],0,'expertly 表示以熟练、专业的方式。'],[1,'Which action is performed expertly?',['a pianist plays a difficult passage cleanly and confidently','a novice guesses every note and stops repeatedly','a listener turns off the instrument'],0,'准确流畅演奏难段体现熟练技巧。'],[1,'Choose the natural sentence.',['She expertly diagnosed the fault.','She expertly the fault yesterday.','She diagnosed expertly to the fault.'],0,'expertly 是修饰动词 diagnosed 的副词。'],[1,'“The surgeon expertly repaired the valve” praises the surgeon’s?',['skill in performing the repair','ability to postpone the operation','ownership of the hospital'],0,'此处称赞修复动作技术精湛。']]);
P('expiry','由 expire 加名词后缀 -y 构成；expire 源自拉丁语 expirare“呼出气息、终止”，现代常指有效期届满。',[1,'证件管理','Check the passport’s expiry before booking the trip; several countries require it to remain valid for months after arrival.','预订旅行前要检查护照有效期；有些国家要求入境后护照仍有数月有效期。','Check the passport’s expiry before booking the trip; / several countries require it to remain valid / for months after arrival.','名词，常用于 expiry date；英式常用 expiry，美式也常说 expiration。','护照停止有效的日期关系到出行资格，符合 expiry。'],['The food was safe to eat because its expiry date had passed several months earlier.','The food was unsafe to eat because its expiry date had passed several months earlier.','日期已过表示超过有效期，不能据此断言仍安全；改为 unsafe。'],[[1,'The expiry of a permit is the point when it?',['stops being valid','is first submitted','is renewed automatically in every case'],0,'expiry 指有效期终止的时点。'],[1,'Which date is an expiry date?',['the last date a medicine may be used as labelled','the day the medicine was manufactured only','the date a patient first heard of the medicine'],0,'expiry date 标示产品有效期的截止时间。'],[1,'In British usage, “the expiry of the contract” means?',['the contract’s validity comes to an end','the contract is translated','the contract is signed for the first time'],0,'expiry 表示合同到期失效。'],[1,'Choose the usual phrase.',['expiry date','expiry to a calendar','expiry very carefully'],0,'expiry date 是固定常见搭配。']]);
P('explicitly','由 explicit 加副词后缀 -ly 构成；explicit 经法语源自拉丁语 explicitus“展开说明的”。',[1,'合同条款','The contract explicitly prohibits sharing client data, so the consultant asked for written approval before using any records in a presentation.','合同明确禁止分享客户数据，因此顾问在演示中使用任何记录前先征求书面批准。','The contract explicitly prohibits sharing client data, / so the consultant asked for written approval / before using any records in a presentation.','副词修饰 stated、forbid、request 等，表示内容明白写出或直言说出，而非暗示。','合同直接写明禁止行为，体现 explicitly。'],['The policy explicitly mentions nothing about data sharing, yet the manager claimed that it clearly names a specific ban.','The policy implicitly discourages data sharing, yet it does not clearly name a specific ban.','没有明文写出某项禁令就不能说 explicitly mentions it。'],[[1,'If a rule explicitly forbids an action, the rule?',['states the prohibition clearly in words','hints at it but never states it','allows it without qualification'],0,'explicitly 指把要求清楚明白地说出。'],[1,'Which instruction is given explicitly?',['“Submit the form by noon,” printed in the notice','a vague gesture toward an office','a rule no one has written or spoken'],0,'书面直接写出截止时间属于明确指示。'],[1,'Choose the closest meaning: “She explicitly denied signing.”',['She clearly stated that she had not signed.','She silently avoided the question.','She signed but hid the document.'],0,'explicitly denied 表示明确否认。'],[1,'Which contrast is correct?',['Explicitly stated means openly stated; implied means suggested indirectly.','Explicitly and accidentally both mean secretly.','Explicitly refers only to speaking loudly.'],0,'explicitness 关乎内容是否明言，不等同音量大小。']]);
P('explicitness','由 explicit 加 -ness 构成，表示把信息充分说出、不靠暗示的明确程度。',[1,'法律写作','The editor increased the explicitness of the safety notice by naming the prohibited chemical and stating the exact steps workers must follow.','编辑提高了安全告示的明确性，写出禁用化学品名称及工人必须遵循的具体步骤。','The editor increased the explicitness of the safety notice / by naming the prohibited chemical / and stating the exact steps workers must follow.','不可数名词，描述信息直接、清晰的程度；与含糊或暗示相对。','告示点名化学品并列明步骤，降低了解读歧义，提高 explicitness。'],['The notice’s explicitness improved when it replaced every direct instruction with hints that workers had to guess at.','The notice’s ambiguity increased when it replaced every direct instruction with hints that workers had to guess at.','把明示改成暗示降低了明确性并增加含糊，不会提高 explicitness。'],[[1,'Explicitness in an instruction means?',['the point is stated clearly and fully','the point is hidden behind a symbol','the instruction is necessarily very long'],0,'explicitness 是内容明言、清楚的性质。'],[1,'Which change increases a form’s explicitness?',['state exactly which documents are required','say “bring something useful” without details','remove the deadline'],0,'明确列出所需文件可减少歧义。'],[1,'Explicitness contrasts most directly with?',['vagueness','accuracy','punctuation'],0,'明确与含糊相对。'],[1,'A writer values explicitness when readers should?',['not have to infer essential requirements','guess what the writer means','ignore all details'],0,'明确表达使读者无需猜测关键要求。']]);
P('exploitation','由 exploit 加 -ation 构成；该动词经法语源自拉丁语 explicare“展开、利用”，可指开发资源或不公平剥削。',[2,'劳动权益','The investigation documented the exploitation of seasonal workers, who were charged illegal fees and denied the wages promised in their contracts.','调查记录了对季节工的剥削：他们被收取非法费用，也拿不到合同承诺的工资。','The investigation documented the exploitation of seasonal workers, / who were charged illegal fees / and denied the wages promised in their contracts.','s1 指对资源的开发利用；s2 指利用他人谋利且不公平，常接 exploitation of workers。','非法收费并克扣工资是对劳动者的不公正利用，符合 s2。'],['The exploitation of a new geothermal field supplied clean heat under a regulated plan that shared benefits fairly with local communities.','The development of a new geothermal field supplied clean heat under a regulated plan that shared benefits fairly with local communities.','公平开发地热资源是资源利用 s1；此句无剥削他人含义，用 development 更合适。'],[[2,'Exploitation of workers usually means?',['unfairly taking advantage of their labour','giving them the pay and protections promised','training them without assigning work'],0,'exploitation s2 指不公平地利用他人劳动获利。'],[1,'The exploitation of a mineral deposit refers to?',['developing and using the resource','protecting it from all use','a dispute between two employees'],0,'资源语境下 exploitation 可指开发、利用。'],[2,'Which case best illustrates exploitative treatment?',['an employer withholds wages and charges workers illegal recruitment fees','a firm pays agreed wages and reimburses travel costs','a union negotiates safer conditions'],0,'克扣工资并收非法费用构成剥削。'],[1,'Which meaning is possible in “the exploitation of solar energy”?',['making practical use of the resource','taking unfair advantage of a person','removing a student from school'],0,'能源语境中表示利用资源。']]);
P('exploitative','由 exploit 加形容词后缀 -ative 构成，常形容不公平利用劳动者、受众或自然资源以获取利益。',[1,'平台经济','The audit found the platform’s payment model exploitative because couriers bore equipment costs while the company controlled their schedules and withheld bonuses.','审计认为该平台的报酬模式具有剥削性，因为骑手承担设备成本，公司却控制排班并扣留奖金。','The audit found the platform’s payment model exploitative / because couriers bore equipment costs / while the company controlled their schedules and withheld bonuses.','形容词，常修饰 labour、relationship、business practice；含不公平获利的批评意味。','公司把成本转给骑手却控制其工作并扣奖金，体现不公平的利益占取。'],['The cooperative’s transparent profit-sharing arrangement was exploitative because every member received the agreed share and could leave freely.','The cooperative’s transparent profit-sharing arrangement was equitable because every member received the agreed share and could leave freely.','公平分配且可自由退出不体现剥削；equitable 更准确。'],[[1,'An exploitative employer is one who?',['unfairly takes advantage of workers for gain','pays agreed wages and respects legal rights','does not employ anyone'],0,'exploitative 描述不公平利用他人谋利。'],[1,'Which business practice is exploitative?',['hiding fees and withholding workers’ earned pay','publishing all fees before customers sign','sharing profits under a voluntary agreement'],0,'隐瞒费用并扣工资是不公平获利。'],[1,'Exploitative most nearly means?',['unfairly taking advantage of someone','equally distributing a benefit','carefully explaining a process'],0,'该词带有剥削、榨取意味。'],[1,'Choose the natural phrase.',['exploitative labour conditions','exploitative to arrive','exploitative into the room'],0,'exploitative 可修饰 labour conditions。']]);
P('exploration','源于拉丁语 explorare“调查、探寻”，经法语进入英语；可指探索陌生地域，也可指研究某一主题。',[1,'海洋考察','The oceanographic team began an exploration of the trench, mapping its slopes and collecting water samples from several depths.','海洋学小组开始探查海沟，绘制坡面图，并从不同深度采集水样。','The oceanographic team began an exploration of the trench, / mapping its slopes / and collecting water samples from several depths.','可数或不可数名词；可接 of + 地域、主题；目的在了解未知情况。','绘图和取样旨在发现海沟情况，是探索活动。'],['The team’s exploration of the trench was a routine delivery of familiar supplies to a fully mapped, well-known site.','The team’s resupply visit to the trench was a routine delivery of familiar supplies to a well-known site.','补给已知地点不是探查未知地区；resupply visit 才准确。'],[[1,'An exploration of an unknown cave aims to?',['discover what the place is like','repeat a route without observing anything','close the cave permanently'],0,'exploration 是为发现而进行的探查。'],[1,'Which is an exploration in the intellectual sense?',['a careful study of how memory affects learning','a list of office supplies','a final answer copied without investigation'],0,'exploration 也可指对主题的深入研究。'],[1,'Choose the natural phrase.',['the exploration of Mars','exploration at to Mars','exploration more quietly'],0,'常用结构为 exploration of + 地点或主题。'],[1,'A scientific exploration usually involves?',['gathering information about something not yet well understood','assuming all answers before collecting evidence','avoiding observation'],0,'探索以调查、发现新信息为目的。']]);
P('exploratory','由 explore 加 -atory 构成，表示为发现事实或检验想法而进行的初步探查。',[1,'医学研究','The clinic ran an exploratory study with a small group first, using the results to refine its questions before a larger trial.','诊所先对一小组人开展探索性研究，并依据结果完善问题，再进行更大规模试验。','The clinic ran an exploratory study with a small group first, / using the results to refine its questions / before a larger trial.','形容词，强调发现信息、形成假设或预试；通常不是最终验证性结论。','小样本先用来完善后续试验问题，体现探索性研究的初步性质。'],['The exploratory trial conclusively proved the treatment works for all patients, leaving no need for further testing.','The confirmatory trial conclusively tested whether the treatment works for the target patients.','探索性试验通常用于初步探查，不能据此声称对所有患者作出决定性证明。'],[[1,'An exploratory interview is designed mainly to?',['discover useful questions and information','deliver a final verdict with no follow-up','repeat a fixed script without listening'],0,'exploratory 表示为了解事实而进行的探查。'],[1,'Which study is exploratory?',['a small preliminary study used to shape later research','a final nationwide trial confirming a set outcome','a report that contains no observations'],0,'初步研究帮助形成后续方案，具有探索性。'],[1,'Exploratory evidence is generally?',['useful for generating or refining ideas','a guarantee that every hypothesis is proved','unrelated to observation'],0,'探索性工作常帮助提出或细化想法，而非保证证明。'],[1,'Choose the natural phrase.',['an exploratory investigation','exploratory of the investigation','exploratory arrived yesterday'],0,'exploratory 可修饰 investigation。']]);
P('explosively','由 explosive 加副词后缀 -ly 构成，可指像爆炸般猛烈地发生，也可描述增长或情绪骤然爆发。',[1,'材料科学','When the sealed canister was overheated, pressure rose until the casing failed explosively and fragments scattered across the test chamber.','密封罐过热时，压力不断上升，最终外壳猛烈炸裂，碎片散落在测试室里。','When the sealed canister was overheated, / pressure rose until the casing failed explosively / and fragments scattered across the test chamber.','副词；可修饰 burst、expand、grow，既可有实际爆炸力，也可比喻突然剧烈增长。','外壳爆裂并散出碎片是字面上的猛烈爆炸。'],['The sealed container opened explosively with no pressure release, no force, and no sudden movement.','The sealed container opened quietly after pressure was released.','毫无突然力量的安静开启与 explosively 不符。'],[[1,'If a pipe bursts explosively, it bursts?',['suddenly and with great force','slowly without any force','only after being painted'],0,'explosively 表示猛烈且突然地。'],[1,'An explosively growing city is growing?',['at a rapidly accelerating rate','at a fixed rate of one house per century','not at all'],0,'比喻用法表示增长极快。'],[1,'Which event is described explosively?',['a pressure vessel ruptures violently','a door closes gently','a plant grows one leaf over a year'],0,'剧烈破裂符合 explosively。'],[1,'Choose the natural sentence.',['Prices rose explosively after the shortage.','Prices explosively on the shelf.','Prices were explosively yesterday.'],0,'副词 explosively 修饰 rose，说明增长方式。']]);
P('expo','经 exposition 缩略而来，表示大型展览会，企业或国家在会上展示产品、服务或想法。',[1,'商业展览','At the annual technology expo, visitors compared working prototypes, spoke with engineers, and watched demonstrations of the new battery system.','在年度科技博览会上，参观者比较了可运行的原型，与工程师交流，并观看了新电池系统的演示。','At the annual technology expo, / visitors compared working prototypes, / spoke with engineers, and watched demonstrations of the new battery system.','可数名词，常指 trade、technology、career 等大型博览会；不只是普通会议。','展位展示产品并提供演示，符合 expo 的展览会义。'],['The expo was a private phone call with no exhibits, displays, or attendees gathered at a venue.','The consultation was a private phone call with no exhibits or public displays.','私下通话不是展示产品与想法的博览会，consultation 更吻合。'],[[1,'A science expo is usually?',['a large event where organisations display projects or products','a private note sent to one person','a chemical reaction in a test tube'],0,'expo 指集中展示成果或产品的大型展会。'],[1,'Which activity fits a career expo?',['employers set up booths and meet job seekers','a court hears a criminal appeal','a family eats dinner at home'],0,'招聘方设展位并与求职者交流，是职业博览会。'],[1,'“The company unveiled its device at an expo” means it?',['displayed the device at a large exhibition','hid the device from every visitor','shipped the device to a warehouse'],0,'expo 是展示产品的展会。'],[1,'Choose the natural phrase.',['a trade expo','an expo to calculate carefully','expo at arriving'],0,'trade expo 是自然搭配。']]);
P('exponential','由 exponent 加 -ial 构成，数学上指含指数的；一般语境也表示增长越来越快。',[1,'数据分析','The number of phishing messages rose at an exponential rate after the stolen mailing list was posted online, doubling repeatedly within days.','被盗邮件名单公开后，钓鱼信息数量呈指数式增长，几天内便反复翻倍。','The number of phishing messages rose at an exponential rate / after the stolen mailing list was posted online, / doubling repeatedly within days.','形容词；数学义与指数有关，日常义描述速度不断加快的增长；不能仅指“很多”。','数量连续翻倍是指数增长的典型模式。'],['The bacteria count increased exponentially by exactly one cell each year at a constant rate.','The bacteria count increased linearly by exactly one cell each year at a constant rate.','每年增加固定数量是线性增长，不是指数增长。'],[[1,'Exponential growth commonly means that a quantity?',['multiplies by a factor over equal time intervals','adds the same fixed amount each interval','remains exactly unchanged'],0,'指数增长的量会在相等间隔内按比例倍增。'],[1,'Which pattern is exponential rather than linear?',['the total doubles every hour','the total gains ten units every hour','the total loses one unit every hour'],0,'固定比例翻倍是指数型变化。'],[1,'A warning says the cost is rising exponentially. It suggests the cost?',['is accelerating very rapidly','has stayed flat for years','is decreasing by a fixed amount'],0,'一般用法强调增长速度越来越快。'],[1,'In mathematics, an exponential expression involves?',['a variable or quantity raised to a power','only a fixed sum of equal addends','a punctuation mark'],0,'数学 exponential 与指数幂有关。']]);
P('exportation','由 export 加名词后缀 -ation 构成，指商品出口的行为、商业活动，也可指被出口的货物。',[1,'国际贸易','A temporary ban on the exportation of untreated timber was introduced to protect local forests and encourage domestic processing.','为保护本地森林并鼓励国内加工，政府暂时禁止出口未经处理的木材。','A temporary ban on the exportation of untreated timber / was introduced / to protect local forests and encourage domestic processing.','名词，偏正式；可数或不可数用法随语境而异，常见 exportation of goods。','禁令针对木材跨境输出，体现出口活动这一义项。'],['The exportation rules required every imported machine to be shipped from the country to a foreign buyer.','The importation rules required every machine brought into the country to meet safety standards.','运入本国是 importation，不是 exportation。'],[[1,'Exportation is the act of?',['sending goods from one country to another for sale','bringing foreign goods into a country','storing goods without moving them'],0,'exportation 指出口行为或业务。'],[1,'A restriction on the exportation of grain limits?',['grain leaving the country','grain entering the country','grain being measured in a warehouse'],0,'出口限制管控商品向国外运出。'],[1,'Which is an example of exportation?',['a factory ships its tea abroad for sale','a shop buys tea from overseas','a farm stores tea before harvest'],0,'向国外发货销售是出口。'],[1,'Choose the natural phrase.',['the exportation of machinery','exportation to imported goods','exportation very quietly'],0,'常用 exportation of + 出口商品。']]);
P('expository','由 exposition 加 -ory 构成，表示旨在解释事实或观点的，而非主要讲故事或抒发情绪。',[1,'写作课程','The lecturer chose an expository essay that explained how the water-treatment plant worked, supporting each stage with diagrams and verified facts.','讲师选了一篇说明文，解释水处理厂如何运行，并用图示和核实过的事实说明各步骤。','The lecturer chose an expository essay / that explained how the water-treatment plant worked, / supporting each stage with diagrams and verified facts.','形容词，常搭配 writing、essay、text；核心是解释和传达信息。','文章解释设施工作原理，属于说明性写作。'],['The expository chapter focused on fictional characters and suspense while carefully avoiding any explanation of the process.','The narrative chapter focused on fictional characters and suspense while avoiding process explanation.','以人物情节和悬念为主、回避解释的章节偏叙事，不是 expository。'],[[1,'An expository paragraph mainly aims to?',['explain a subject clearly','create suspense through a fictional plot','express a character’s feelings without explanation'],0,'expository 表示以说明为目的。'],[1,'Which text is expository?',['a guide explaining how a solar panel converts light into electricity','a mystery scene ending with an unknown culprit','a lyric expressing grief through imagery'],0,'解释工作原理的指南属于说明文本。'],[1,'Expository writing is most likely to use?',['facts, definitions, and clear explanation','only dialogue and plot twists','a list of unrelated sounds'],0,'说明文通过事实和解释传达信息。'],[1,'Choose the natural phrase.',['an expository essay','an expository arrived late','expository under the chair'],0,'expository 可修饰 essay。']]);
P('expound','源于拉丁语 exponere“摆出、解释”，经法语进入英语，表示详细说明观点、文本或信念。',[1,'学术讲座','In her lecture, the historian expounded the treaty’s clauses slowly, showing how each provision changed the balance of power.','讲座中，历史学家逐条详细阐释条约条款，说明每项规定如何改变权力平衡。','In her lecture, the historian expounded the treaty’s clauses slowly, / showing how each provision / changed the balance of power.','正式及物动词；常接 idea、theory、doctrine、text；也可用 expound on/upon。','她逐项解释条文及其影响，符合 expound 的详细说明义。'],['The analyst expounded the proposal by refusing to explain its assumptions, terms, or expected effects.','The analyst summarised the proposal without discussing its assumptions or effects.','拒绝解释内容不是 expound；若只是简短概括可用 summarised。'],[[1,'To expound a theory is to?',['explain it at length and in detail','erase it from a document','disagree with it without reading it'],0,'expound 表示详细说明或阐释。'],[1,'Which construction is standard?',['expound on the evidence','expound at the evidence','expound for the evidence'],0,'可以说 expound on/upon something，也可直接接宾语。'],[1,'A professor expounds a difficult passage by?',['unpacking its meaning and reasoning','skipping every sentence','changing the subject to lunch'],0,'阐释文本需解释其含义和论证。'],[1,'Choose the closest paraphrase: “He expounded his position.”',['He explained his position fully.','He concealed his position.','He withdrew his position without comment.'],0,'expound 表示展开说明。']]);
P('expressionism','由 expression 加 -ism 构成，指二十世纪艺术与文学中的表现主义，常扭曲现实形象以突出情感。',[1,'艺术史','The exhibition’s expressionism used distorted figures and abrupt colour contrasts to convey anxiety rather than to reproduce appearances realistically.','展览中的表现主义作品用变形人物和强烈色彩对比传达焦虑，而非写实再现外观。','The exhibition’s expressionism used distorted figures and abrupt colour contrasts / to convey anxiety / rather than to reproduce appearances realistically.','不可数艺术流派名；重在情感表达，不等于所有抽象艺术。','变形造型与强烈色彩服务于情绪表达，符合表现主义特征。'],['The curator called the painting expressionism because it copied every visible detail in calm, photographic realism.','The curator called the painting realism because it copied every visible detail with photographic accuracy.','逐项照实再现属于 realism，与通过变形表达情绪的 expressionism 有别。'],[[1,'Expressionism in art often prioritises?',['emotional effect over realistic appearance','exact photographic reproduction','the chemical composition of paint only'],0,'表现主义强调情感表达，不以写实为首要目标。'],[1,'Which technique is associated with expressionism?',['distorting forms to intensify a feeling','copying a scene with measured photographic accuracy','avoiding all emotional content'],0,'刻意变形可加强情绪表达。'],[1,'Expressionism developed as a movement in?',['modern art and literature','ancient arithmetic only','the law of shipping'],0,'Expressionism 是现代艺术和文学的重要流派名称。'],[1,'A portrait with exaggerated angles meant to convey fear could be?',['expressionist','a literal photograph','a shipping invoice'],0,'夸张变形以表现恐惧符合表现主义做法。']]);
P('expressionless','由 expression 加 -less 构成，表示脸、眼神或声音没有显露情感。',[1,'法庭观察','The witness remained expressionless as the verdict was read, giving the reporters no visible clue about how she felt.','宣读裁决时，证人仍面无表情，记者看不出她的感受。','The witness remained expressionless as the verdict was read, / giving the reporters no visible clue / about how she felt.','形容词，常修饰 face、look、voice；不表示内心一定没有情感，只表示外在未显露。','记者无法从她的神情判断情绪，说明表情未流露。'],['The expressionless actor showed delight through a broad smile and animated eyes throughout the scene.','The expressive actor showed delight through a broad smile and animated eyes throughout the scene.','明显微笑和生动眼神表达情绪，不是 expressionless。'],[[1,'An expressionless face shows?',['no visible emotion','an unmistakable grin','tears and obvious anger'],0,'expressionless 描述脸上看不出情绪。'],[1,'If a speaker’s voice is expressionless, it sounds?',['flat, with little feeling conveyed','full of changing emotion','too loud to understand'],0,'声音平淡、没有情感起伏是 expressionless。'],[1,'Does expressionless prove that someone feels nothing?',['No; it describes what is outwardly shown.','Yes; it proves a lack of all inner feeling.','Yes; it means the person cannot speak.'],0,'该词描述外在表现，不足以判断内心感受。'],[1,'Choose the natural phrase.',['an expressionless stare','expressionless very quickly','expressionless to the doorway'],0,'expressionless 可修饰 stare。']]);
P('expressiveness','由 expressive 加 -ness 构成，指面容、声音、语言或艺术传达情感和意义的能力。',[1,'表演','The actor’s expressiveness let the audience follow the character’s changing confidence through small shifts in posture and voice.','演员的表现力让观众从细微的姿态和声音变化中看出角色信心的起伏。','The actor’s expressiveness let the audience follow the character’s changing confidence / through small shifts in posture and voice.','不可数性质名词；可用于艺术、语言、面部表情或声音，描述表达能力。','姿态和声音的细微变化传递角色情绪，体现 expressiveness。'],['The mask’s expressiveness was praised because it concealed every emotion and gave viewers no clue about the character.','The mask’s blankness was evident because it concealed every emotion and gave viewers no clue about the character.','完全遮蔽情绪体现 blankness，而不是传情达意的表现力。'],[[1,'A performer’s expressiveness is the ability to?',['communicate feeling or meaning effectively','memorise a schedule without understanding it','remain unseen on stage'],0,'expressiveness 指表达情感或意义的能力。'],[1,'Which instrument has greater expressiveness in a performance?',['one that can convey subtle changes in mood','one that produces only one unchanging tone','one that is never played'],0,'能呈现细腻情绪变化的乐器更具表现力。'],[1,'Expressiveness can describe?',['a voice, a face, or a work of art','only the price of a ticket','only a person’s height'],0,'该名词适用于多种表达媒介。'],[1,'Choose the closest meaning: “The language gains expressiveness through metaphor.”',['It becomes better able to convey ideas and feeling.','It becomes impossible to understand.','It loses every descriptive word.'],0,'比喻使语言更能传达意义与情感。']]);
P('expressly','由 express 加副词后缀 -ly 构成，可表示明确说出，也可表示专门为某目的而做。',[1,'产品说明','The manufacturer expressly states that the adapter is not waterproof, so customers should keep it away from sinks and outdoor rain.','制造商明确说明该适配器不防水，因此用户应让它远离水槽和户外雨水。','The manufacturer expressly states that the adapter is not waterproof, / so customers should keep it away / from sinks and outdoor rain.','副词；依语境可表示明言，也可表示特意、专为某目的。','说明书直接写明不防水，体现“明确地”这一义。'],['The room was expressly built for quiet study, although the builders never planned it for study and designed it as a noisy workshop.','The room was originally built as a noisy workshop and was not expressly designed for study.','若并非专门为学习而建，就不能称 expressly built for study。'],[[1,'If a rule expressly prohibits recording, it?',['clearly says that recording is forbidden','only hints that recording may be unwelcome','states that recording is required'],0,'此处表示明确写出或说出。'],[1,'A room built expressly for experiments was built?',['specifically for that purpose','by accident for an unrelated purpose','without any intended use'],0,'此处表示专门为某目的而建。'],[1,'Which sentence uses expressly to mean clearly stated?',['The label expressly warns users not to mix the chemicals.','The lab was expressly designed for chemistry.','The package arrived on Tuesday.'],0,'明示警告对应明确说明义。'],[1,'“She came expressly to return the key” means she came?',['specifically for the purpose of returning it','without any particular reason','to hide the key permanently'],0,'此处表示她专程为归还钥匙而来。']]);
P('expropriate','由 ex-“取出”与 proprius“自己的、财产”构成，指政府或权力机构依法或强制取走私人土地、资产，有时给予补偿。',[1,'土地征收','The state expropriated a strip of farmland to build the flood barrier, paying the owners compensation under the public-works statute.','政府为修建防洪堤征收了一条农田，并按公共工程法规向业主支付补偿。','The state expropriated a strip of farmland / to build the flood barrier, / paying the owners compensation under the public-works statute.','正式及物动词，常以 land/property/assets 为宾语；征收是否补偿由制度和具体语境决定。','政府为公共工程取走私人土地并依法补偿，符合 expropriate。'],['The state expropriated no land because the owners kept full control and no property was taken for the project.','The state purchased no land because the owners kept full control and no property was taken for the project.','没有取走私人资产就没有 expropriation；此句表达未征收或购买。'],[[1,'To expropriate private land is to?',['take it from its private owners, often under state authority','rent it voluntarily for one afternoon','survey it without changing ownership'],0,'expropriate 指取走私人财产，常由政府实施。'],[1,'Which situation is expropriation?',['a government takes a parcel for a public project under law','a neighbour borrows a shovel with permission','a buyer pays the agreed price in a normal sale'],0,'政府依法取走土地用于公共项目符合征收。'],[1,'Does expropriate always mean that no compensation is paid?',['No; compensation may be provided.','Yes; compensation is impossible by definition.','Yes; it means the owner gifts the land.'],0,'征收有时会依法给予补偿。'],[1,'Choose the natural object.',['expropriate a property','expropriate at a property','expropriate with a property'],0,'expropriate 是及物动词，可直接接资产作宾语。']]);
P('expulsion','由 expel 加名词后缀 -sion 构成；expel 经法语源自拉丁语 expellere“驱逐、逐出”。',[1,'校园纪律','After a formal hearing, the student faced expulsion for repeatedly threatening classmates despite several documented warnings.','经过正式听证，尽管已有多次书面警告，该学生仍因反复威胁同学而面临开除。','After a formal hearing, / the student faced expulsion / for repeatedly threatening classmates despite several documented warnings.','不可数名词或单数事件名词；可指被学校、俱乐部开除，也可指驱逐出境。','正式纪律程序可能将学生逐出学校，属于 expulsion。'],['The student’s expulsion meant the school welcomed him back immediately and restored every membership without a hearing.','The student’s reinstatement meant the school welcomed him back immediately and restored every membership.','恢复资格、重新接纳是 reinstatement，与 expulsion 正相反。'],[[1,'A student’s expulsion from school means the student is?',['officially removed from the school','given a new classroom','praised for excellent attendance'],0,'expulsion 可指学校正式开除。'],[1,'A country may order the expulsion of a foreign resident by?',['requiring that person to leave the country','granting permanent citizenship','extending the person’s visitor pass'],0,'驱逐出境是要求其离开国家。'],[1,'Which process may precede expulsion from a club?',['a formal disciplinary hearing','a birthday celebration','a routine change of meeting room'],0,'纪律听证可能决定是否开除成员。'],[1,'Choose the natural phrase.',['expulsion from the organisation','expulsion to be friendly','expulsion at the membership'],0,'常用 expulsion from + 组织或地点。']]);
P('extant','源自拉丁语 extare“突出、存在”，经法语进入英语；常形容仍保存下来的书籍、记录、物种或建筑。',[1,'档案','Only three extant copies of the early atlas are known, and each is kept in a climate-controlled collection to prevent further deterioration.','已知这部早期地图集仅存三册，每册都保存在恒温恒湿的馆藏环境中，以免继续损坏。','Only three extant copies of the early atlas are known, / and each is kept in a climate-controlled collection / to prevent further deterioration.','正式形容词，通常置于名词前；强调历经时间或破坏后仍然保存。','仍保存下来的早期地图集副本属于 extant copies。'],['The extant manuscript had been completely destroyed centuries ago and no copy survives today.','The lost manuscript had been completely destroyed centuries ago and no copy survives today.','已彻底毁掉、没有副本存世的手稿不是 extant。'],[[1,'An extant record is one that?',['still survives and can be found','was planned but never created','was destroyed with no surviving copy'],0,'extant 指仍然存世、现存的。'],[1,'Which item is extant?',['a surviving medieval charter in an archive','a book known only from a lost catalogue entry','a building that was demolished with no remains'],0,'档案中保存的契约仍然存世。'],[1,'Extant is especially natural when describing?',['old texts or species that have survived','a future proposal not yet approved','a person’s next appointment'],0,'extant 常用于强调古物、记录等仍保存。'],[1,'Choose the natural phrase.',['the oldest extant copy','the extant next week','extant to read aloud'],0,'oldest extant copy 是自然搭配。']]);
P('extemporaneous','由 ex tempore“当场、即席”衍生，表示未经预先准备而当场发表或完成的。',[1,'演讲','The chair asked for an extemporaneous response, so Lina spoke from her notes of the discussion rather than reading a prepared statement.','主席要求即席回应，于是莉娜依据讨论中的笔记发言，而没有照读事先准备好的稿子。','The chair asked for an extemporaneous response, / so Lina spoke from her notes of the discussion / rather than reading a prepared statement.','形容词，常修饰 speech、remark、response；表示即席而非预先写好，并不一定意味着毫无思考。','她没有读预制发言稿，而是当场回应，符合 extemporaneous。'],['The supposedly extemporaneous speech was memorised word for word from a script prepared weeks earlier.','The carefully rehearsed speech was memorised word for word from a script prepared weeks earlier.','提前数周写好并背熟的是准备好的演讲，不是即兴发言。'],[[1,'An extemporaneous remark is made?',['at the moment, without prior preparation','from a script rehearsed for weeks','after the event has ended'],0,'extemporaneous 指当场发表、事先未准备。'],[1,'Which is an extemporaneous speech?',['a brief answer composed while responding to a new question','a speech read from a finished manuscript','a recording made before the meeting'],0,'针对新问题临场组织的发言是即兴的。'],[1,'Does extemporaneous necessarily mean careless?',['No; it means not prepared in advance.','Yes; it means knowingly inaccurate.','Yes; it means impossible to understand.'],0,'词义强调准备时机，不直接评判质量。'],[1,'Choose the natural collocation.',['an extemporaneous answer','an extemporaneous last year','extemporaneous at the question'],0,'extemporaneous 可修饰 answer。']]);
P('extendable','由 extend 加 -able 构成；extend 源自拉丁语 extendere“伸展”，表示可被拉长或延长。',[1,'工程设计','The survey pole is extendable, allowing the crew to measure ceilings at different heights without carrying several separate rods.','这根测量杆可以伸长，让工作人员测量不同高度的天花板，而不必携带多根杆子。','The survey pole is extendable, / allowing the crew to measure ceilings at different heights / without carrying several separate rods.','形容词，常描述杆、梯、线缆或期限；具体由物理延伸还是时间延长取决于名词。','测量杆可拉长以适应不同高度，体现 extendable。'],['The extendable ladder could not be lengthened, so the crew used its fixed short setting to reach the roof.','The fixed-length ladder could not be lengthened, so the crew used another tool to reach the roof.','不能变长的梯子应称 fixed-length，不是 extendable。'],[[1,'An extendable table can be?',['made longer by adding or moving parts','used only once and then discarded','folded into a liquid'],0,'extendable 表示可以延长或伸展。'],[1,'Which deadline is extendable?',['one that may be prolonged by approval','one that ended permanently yesterday','one that cannot be changed under any circumstances'],0,'时间期限可以延长时称 extendable。'],[1,'A telescoping pole is extendable because it?',['can be lengthened','cannot move at all','is made only of fabric'],0,'套接结构能拉长，符合 extendable。'],[1,'Choose the natural phrase.',['an extendable cable','extendable at the cable','extendable to arrive'],0,'extendable 可作形容词修饰 cable。']]);
P('extensively','由 extensive 加 -ly 构成；extensive 经法语源自拉丁语 extendere“伸展”，副词表示范围广或深入细致。',[1,'文献综述','The research team searched the medical literature extensively before designing the trial, reviewing studies in several languages and databases.','研究团队在设计试验前广泛检索医学文献，查阅了多种语言和多个数据库中的研究。','The research team searched the medical literature extensively / before designing the trial, / reviewing studies in several languages and databases.','副词，可修饰 research、study、use 等；强调范围广或做得深入，不只表示时间长。','团队跨语言、跨数据库广泛搜寻，体现 extensively。'],['The committee researched the issue extensively by reading only one sentence and ignoring every other source.','The committee researched the issue superficially by reading only one sentence and ignoring every other source.','只读一句且忽略其他资料是浅尝辄止，不是广泛深入研究。'],[[1,'To test a device extensively is to test it?',['in a wide-ranging or thorough way','once without recording anything','only after throwing it away'],0,'extensively 指广泛或深入地进行。'],[1,'Which sentence uses extensively naturally?',['The archive has been extensively catalogued.','The archive extensively yesterday.','Extensively is the archive.'],0,'副词修饰 has been catalogued，表示编目范围广、工作充分。'],[1,'A drug was used extensively across several hospitals. This means it was used?',['widely at many sites','once by one patient only','not at all'],0,'across several hospitals 表明使用范围广。'],[1,'Extensively differs from briefly in that it suggests?',['broad or thorough coverage','a shorter duration','a lower price'],0,'extensively 强调范围或深度，briefly 强调简短。']]);
P('extenuate','源自拉丁语 extenuare“使变轻、减弱”，经法语进入英语；表示提出理由以减轻过错的严重性。',[1,'纪律处分','The student admitted copying the passage but argued that severe illness should not extenuate the decision to submit it as original work.','学生承认抄写了该段文字，但认为病情严重并不能减轻把它当原创提交的过错。','The student admitted copying the passage / but argued that severe illness should not extenuate / the decision to submit it as original work.','正式及物动词，常用于否定句或搭配 circumstances；表示减轻罪责的理由，不等于证明无罪。','讨论疾病是否能减轻抄袭过错，正是 extenuate 的用法。'],['The judge said that the apology extenuated the fraud by proving that no deception had occurred.','The judge said that the apology did not extenuate the fraud because the evidence still showed deliberate deception.','道歉不能抹去蓄意欺诈事实；若无理由减轻严重性，不应称 extenuate。'],[[1,'To extenuate a wrongdoing is to?',['offer a reason that makes it seem less serious','prove that it never happened','repeat it more often'],0,'extenuate 指试图减轻过错的严重程度。'],[1,'“Nothing can extenuate the cruelty” means?',['No excuse makes the cruelty seem less bad.','The cruelty was never committed.','The cruelty should be rewarded.'],0,'该句表示没有理由可减轻其严重性。'],[1,'Which construction is natural?',['extenuating circumstances','extenuating the calendar','extenuate from a circumstance'],0,'extenuating circumstances 是常见搭配。'],[1,'Does extenuate mean fully excuse someone?',['No; it means lessen the apparent seriousness.','Yes; it proves the act was legal.','Yes; it means reward the person.'],0,'减轻严重性不等同完全免除责任。']]);
P('exterminate','由 ex-“彻底”与 terminare“划定边界、终止”构成，经拉丁语进入英语；指彻底消灭一群动物或人。',[1,'害虫治理','The contractor sealed the food stores and treated the nesting sites to exterminate the invasive beetles without exposing nearby families to the pesticide.','承包商封存食品并处理巢穴，以彻底消灭入侵甲虫，同时避免附近家庭接触杀虫剂。','The contractor sealed the food stores and treated the nesting sites / to exterminate the invasive beetles / without exposing nearby families to the pesticide.','及物动词，通常接害虫、入侵物种或群体；表示彻底消灭，语气强烈。','处理巢穴并消灭整个入侵甲虫群体，符合 exterminate。'],['The wildlife team exterminated the invasive rats by feeding them and protecting every nest so the population could grow.','The wildlife team preserved the invasive rats by feeding them and protecting every nest.','喂养并保护巢穴会使种群增长，不是彻底消灭。'],[[1,'To exterminate a pest population is to?',['destroy it completely','move one animal to another room','count it without changing its numbers'],0,'exterminate 表示彻底消灭。'],[1,'Which measure is intended to exterminate an infestation?',['treat all nesting sites until the pest population is eliminated','leave food out to attract more pests','record the pest names and take no action'],0,'彻底处理全部巢穴旨在根除虫害。'],[1,'Exterminate is stronger than merely?',['reduce the number','identify the species','observe its movement'],0,'exterminate 表示消灭殆尽，比减少数量更强。'],[1,'Choose the natural object.',['exterminate an invasive species','exterminate at an invasive species','exterminate to an invasive species'],0,'exterminate 是及物动词，直接接被消灭的对象。']]);
P('extermination','由 exterminate 加名词后缀 -ation 构成，表示彻底消灭某一动物或人群，常指有意实施的杀戮。',[1,'历史研究','The historian documented the extermination of the island’s rat population after the species destroyed nesting grounds used by native birds.','当地鼠类破坏本土鸟类筑巢地后，历史学家记录了岛上鼠群被彻底消灭的过程。','The historian documented the extermination of the island’s rat population / after the species destroyed nesting grounds / used by native birds.','名词，语气严肃；可描述害虫根除，也可指人类遭受的大规模灭绝性杀戮。','整个鼠群被清除，体现“彻底消灭”的名词义。'],['The extermination of the pest was completed when the colony continued to thrive and produced many new nests.','The failed extermination left the pest colony thriving and producing many new nests.','种群继续繁衍说明消灭并未完成，应称失败的根除行动。'],[[1,'Extermination of a pest means?',['complete destruction of its population','a modest decline in sightings','a scientific name change'],0,'extermination 指彻底消灭种群。'],[1,'Why should historians use the word extermination carefully?',['It can refer to deliberate mass killing and carries grave force.','It means a harmless change of address.','It is a casual synonym for studying animals.'],0,'该词可指大规模、有意的杀戮，语气沉重。'],[1,'Which outcome demonstrates extermination?',['no members of the targeted pest population remain','a few pests move to another field','the population is counted but unchanged'],0,'目标种群被全部消灭才是根除。'],[1,'Choose the related verb.',['exterminate','examine','extend'],0,'extermination 对应动词 exterminate。']]);
P('externality','由 external 加经济学后缀 -ity 构成，经济学术语，指生产或消费影响到未参与交易的第三方。',[1,'环境经济','The factory’s smoke imposed a health cost on nearby residents, an externality not reflected in the price paid by buyers.','工厂烟尘给附近居民带来健康成本，这种外部性没有反映在买家的价格中。','The factory’s smoke imposed a health cost on nearby residents, / an externality not reflected in the price / paid by buyers.','经济学名词；可为负外部性（第三方受损）或正外部性（第三方受益）。','附近居民承担了交易之外的健康成本，构成负 externality。'],['The factory’s private fuel bill was an externality because only the factory paid it and no third party was affected.','The factory’s private fuel bill was an internal cost because the factory paid it and no third party was affected.','企业自己承担的成本属于内部成本，不是影响第三方的外部性。'],[[1,'An economic externality occurs when?',['a transaction affects a third party outside the buyer-seller exchange','a buyer pays the listed price to a seller','a firm counts its own payroll expense'],0,'externality 的核心是影响未参与交易的第三方。'],[1,'Noise imposed on neighbours by a factory is a?',['negative externality','private benefit paid only to the factory','tax receipt with no outside effect'],0,'噪声损害邻居，属于负外部性。'],[1,'A park that improves nearby air quality for non-paying residents creates?',['a positive externality','an internal production cost only','a private loss to every resident'],0,'第三方免费受益，构成正外部性。'],[1,'Which is not by itself an externality?',['a company’s own electricity bill','pollution harming people outside the firm','a vaccine reducing transmission to others'],0,'仅由公司自己承担的电费不是第三方效应。']]);
P('externally','由 external 加副词后缀 -ly 构成，可表示从外部作用或从外观层面看。',[1,'系统工程','The unit can be powered externally through the backup port, so technicians do not need to open its sealed battery compartment.','该设备可通过备用接口从外部供电，因此技术人员无需打开密封电池仓。','The unit can be powered externally through the backup port, / so technicians do not need to open / its sealed battery compartment.','副词；可指来自系统外部，也可指外表上呈现；依句中对比判断。','电源从设备外部经接口输入，符合 externally 的来源义。'],['The sealed unit was powered externally even though every cable was disconnected and its only energy source was inside the device.','The sealed unit was powered internally even though every cable was disconnected and its only energy source was inside the device.','所有线缆断开且能源在设备内，说明供能来自内部，不是 externally。'],[[1,'A device powered externally receives power?',['from a source outside the device','only from its internal battery','from no source at all'],0,'externally powered 指由外部提供电力。'],[1,'A person may appear externally calm while?',['feeling anxious inside','having no outward appearance','being located outside the building'],0,'externally 也可表示从外表看；外在平静不等于内心平静。'],[1,'Which phrase means “from outside the system”?',['externally supplied data','internally generated data','data deleted permanently'],0,'externally 与 externally supplied 表示外部输入。'],[1,'Choose the natural sentence.',['The casing is externally damaged.','The casing externally under the table.','Externally the casing was it.'],0,'externally 可作方式副词修饰 damaged，指外表受损。']]);
P('extinction','源自拉丁语 exstinguere“熄灭、扑灭”，经法语进入英语；常指物种灭绝，也可指习俗或活动消亡。',[1,'生态保护','Conservationists restored the wetland before the local frog reached extinction, because its breeding pools had nearly disappeared.','本地青蛙的繁殖水塘几乎消失，保护人员赶在它灭绝前修复了湿地。','Conservationists restored the wetland / before the local frog reached extinction, / because its breeding pools had nearly disappeared.','不可数名词；常见 extinction of a species、face extinction、go extinct；表示不再存在。','青蛙若不再有存活个体，即达到 extinction。'],['The species avoided extinction because its last surviving population died out completely and no individuals remained.','The species faced extinction because its last surviving population was dying out and few individuals remained.','所有个体死亡意味着已经灭绝，不能说成功避免 extinction。'],[[1,'A species reaches extinction when?',['no living members of it remain','its population increases steadily','one animal moves to another habitat'],0,'物种灭绝意味着不再有存活个体。'],[1,'Which action can reduce extinction risk?',['protecting the habitat needed for breeding','destroying the last nesting area','capturing every animal without a survival plan'],0,'保护繁殖栖息地能降低灭绝风险。'],[1,'The extinction of a custom means the custom?',['has disappeared from use','is newly popular','is protected by law'],0,'extinction 也可比喻一种习俗彻底消亡。'],[1,'Choose the natural phrase.',['face extinction','extinction to travel','extinction more quickly than'],0,'face extinction 是常见表达。']]);
P('extinguisher','由 extinguish 加施事后缀 -er 构成；extinguish 源自拉丁语 exstinguere“熄灭”，指用于扑灭火焰的装置。',[1,'消防安全','A trained worker used the correct powder extinguisher on the electrical fire and kept a clear exit behind her.','受过训练的员工对电气火灾使用了合适的干粉灭火器，并确保身后出口畅通。','A trained worker used the correct powder extinguisher / on the electrical fire / and kept a clear exit behind her.','可数名词，通常出现在 fire extinguisher 中；灭火介质须与火源类型匹配。','员工用干粉装置灭火，extinguisher 在此指灭火器。'],['The extinguisher fed more fuel into the flames and increased the fire instead of stopping it.','The fuel pump fed more fuel into the flames and increased the fire instead of stopping it.','灭火器的功能是扑灭火焰，不是供燃料；供油装置才会加剧火势。'],[[1,'A fire extinguisher is designed to?',['discharge an agent that puts out a fire','supply oxygen to the flames','measure the building’s height'],0,'extinguisher 指用来扑灭火灾的设备。'],[1,'Why should a worker choose the correct extinguisher?',['Different fires require suitable extinguishing agents.','Every extinguisher is designed only for paper fires.','The device is used to increase heat.'],0,'灭火剂需适用于相应火源类型。'],[1,'Which phrase is standard?',['fire extinguisher','extinguisher the fire by fuel','extinguisher at the flame'],0,'fire extinguisher 是固定搭配。'],[1,'A portable cylinder of dry powder used on a small fire is an?',['extinguisher','exhaust pipe','experimenter'],0,'干粉灭火器是 extinguisher。']]);
P('extol','源自拉丁语 extollere“高举、抬升”，经法语进入英语，表示热情而高度地赞扬。',[1,'人物评论','Colleagues extolled the nurse’s patience, noting that she explained every procedure clearly even during the busiest shifts.','同事们高度赞扬护士的耐心，指出她即使在最忙的班次也会清楚解释每项操作。','Colleagues extolled the nurse’s patience, / noting that she explained every procedure clearly / even during the busiest shifts.','正式及物动词，常接 virtues、work、achievement；比普通 praise 语气更强、更热情。','同事们公开称赞她的耐心和工作方式，符合 extol。'],['The reviewers extolled the novel by calling it worthless, dull, and poorly written.','The reviewers condemned the novel by calling it worthless, dull, and poorly written.','负面评价是 condemn，不是 extol。'],[[1,'To extol someone’s work is to?',['praise it highly and warmly','hide it from the public','criticise it as worthless'],0,'extol 表示高度赞扬。'],[1,'Which sentence uses extol correctly?',['The report extols the volunteers’ courage.','The report extols at the volunteers’ courage.','The report extol to the volunteers’ courage.'],0,'extol 是及物动词，可直接接赞扬对象。'],[1,'A speaker extols a book by?',['celebrating its exceptional qualities','listing only its spelling errors','refusing to discuss it'],0,'热情肯定作品优点是 extol。'],[1,'Extol is closest in meaning to?',['laud','erase','misplace'],0,'laud 同样表示赞扬。']]);
P('extraction','由 extract 加名词后缀 -ion 构成；extract 源自拉丁语 extrahere“向外拉出”，可指取出过程，也可指人的出身。',[1,'牙科','The dentist explained that extraction would be necessary because the cracked molar could not be repaired and infection had reached its root.','牙医解释说必须拔除这颗裂开的臼齿，因为它无法修复，感染已到达牙根。','The dentist explained that extraction would be necessary / because the cracked molar could not be repaired / and infection had reached its root.','s1 指拔牙、提取数据或物质的过程；s2 指某人的家庭或民族出身。','拔除无法修复的牙齿是 extraction 的 s1。'],['The biographer called the singer “of Irish extraction” because she had extracted a tooth while touring Ireland.','The biographer called the singer “of Irish extraction” because her family had come from Ireland.','of Irish extraction 指爱尔兰裔出身，并非从爱尔兰提取音乐。'],[[1,'A tooth extraction is?',['the process of removing a tooth','the process of polishing a tooth','a dental check-up with no treatment'],0,'extraction s1 可指拔牙、取出。'],[2,'“A writer of Polish extraction” means the writer?',['has Polish family or ethnic origins','has extracted a book from Poland','was born only in a Polish hospital'],0,'extraction s2 指家庭或民族出身。'],[1,'Data extraction from a database means?',['retrieving selected information','deleting the entire database permanently','writing an unrelated poem'],0,'提取数据库数据属于移出信息。'],[2,'Which phrase uses extraction to mean origin?',['a poet of Caribbean extraction','the extraction of oil from rock','the extraction of a damaged tooth'],0,'of Caribbean extraction 表示族裔或家庭来源，不是从当地取出某物。']]);
P('extracurricular','由 extra-“之外”与 curriculum“课程”组合而成，指正式课程之外开展的活动。',[1,'校园生活','The debate club is extracurricular: students meet after classes, practise argumentation, and earn no credit toward their required history course.','辩论社属于课外活动：学生课后聚会练习论证，不计入必修历史课学分。','The debate club is extracurricular: / students meet after classes, practise argumentation, / and earn no credit toward their required history course.','形容词，常修饰 activity、club、programme；活动虽在课程之外，仍可能由学校组织。','辩论社不计入必修课程学分，符合 extracurricular。'],['The required mathematics lecture was extracurricular because every student had to attend it for course credit.','The required mathematics lecture was curricular because every student had to attend it for course credit.','必修并计入课程学分的讲座属于课程内，不是 extracurricular。'],[[1,'An extracurricular activity takes place?',['in addition to the official curriculum','as a required part of every lesson','only during a final examination'],0,'extra-curricular 指正式课程之外的活动。'],[1,'Which is usually extracurricular?',['a student drama club after class','a required algebra lesson for credit','an exam listed in the course syllabus'],0,'课后戏剧社通常属于课外活动。'],[1,'Does extracurricular necessarily mean unsupervised?',['No; a school may organise it outside formal courses.','Yes; it can never be organised by a school.','Yes; it must be illegal.'],0,'课外活动仍可由学校组织和监管。'],[1,'Choose the natural phrase.',['extracurricular activities','extracurricular at studying','extracurricular of the curriculum only'],0,'extracurricular activities 是常见搭配。']]);
P('extradition','由 extra- 与拉丁语 traditio“移交”构成，指把被控或已定罪者移交至另一司法辖区受审或服刑。',[1,'国际司法','The court reviewed the extradition request before allowing the suspect to be transferred abroad to face charges under the treaty.','法院先审查引渡请求，再决定是否依据条约将嫌疑人移交国外接受指控审理。','The court reviewed the extradition request / before allowing the suspect to be transferred abroad / to face charges under the treaty.','法律名词；通常说 extradition of a person to a country；须依条约和法律程序进行。','跨境移交嫌疑人接受审理正是 extradition。'],['The extradition sent the suspect back home for trial, although no court or government transferred the person across a jurisdictional border.','The domestic transfer sent the suspect to another local court, with no cross-border extradition.','没有跨境移交就不构成国际引渡；普通国内移送不是 extradition。'],[[1,'Extradition is the legal transfer of a person?',['to another jurisdiction for trial or punishment','to a hospital for routine care','to a different room inside the same house'],0,'引渡是移交至另一司法辖区。'],[1,'A court considering extradition may ask whether?',['a treaty and legal conditions permit the transfer','the suspect likes the destination’s weather','the transfer will change the person’s name'],0,'引渡需符合适用法律和条约条件。'],[1,'Which case is extradition?',['one country transfers an accused person to another for trial','a prisoner is moved between two rooms in one jail','a witness changes lawyers'],0,'跨国移交被告受审符合 extradition。'],[1,'Choose the natural phrase.',['an extradition request','extradition to arrest a calendar','extradition at the trial yesterday'],0,'extradition request 是常见法律搭配。']]);
P('extraneous','源自拉丁语 extraneus“外来的”，可指讨论中无关、不必要的内容，也可指来自系统之外的因素。',[1,'编辑审阅','The editor removed extraneous paragraphs that repeated the same background, allowing the report’s central evidence to appear clearly.','编辑删掉了重复介绍背景的无关段落，让报告的核心证据更清晰。','The editor removed extraneous paragraphs / that repeated the same background, / allowing the report’s central evidence to appear clearly.','s1 指与主题无关或多余；s2 指源于系统之外。语境中可借 outside/external 判定来源义。','重复且偏离主题的段落属于 s1 的无关内容。'],['The reviewer removed an extraneous paragraph that directly stated the report’s central finding and was essential to its argument.','The reviewer removed a redundant paragraph that repeated an already stated finding.','核心发现且论证必需的段落并非无关；若只是重复则 redundant 才合适。'],[[1,'Extraneous details in a report are?',['irrelevant or unnecessary to its main point','essential evidence for its conclusion','the report’s title and author'],0,'extraneous s1 指无关、多余的内容。'],[2,'An extraneous signal entering a circuit comes?',['from outside the circuit or system','from the system’s intended internal source','from the written conclusion only'],0,'extraneous s2 可表示来自系统外部。'],[1,'Which sentence contains extraneous material?',['a report on bridges includes a long unrelated recipe','a bridge report lists its load tests','an engineer explains a crack relevant to safety'],0,'无关食谱与桥梁报告主题无关。'],[2,'A scientist controls an extraneous variable because it?',['originates outside the process being studied','is the main measured outcome','is the published conclusion'],0,'外部来源变量可影响研究结果，因此需控制。']]);
P('extraordinarily','由 extraordinary 加副词后缀 -ly 构成；extraordinary 由 extra 与 ordinary 组合，表示远超寻常。',[1,'医疗记录','The patient recovered extraordinarily quickly after the operation, but the surgeon still scheduled follow-up visits to monitor healing.','患者术后恢复得格外快，但外科医生仍安排复诊观察愈合情况。','The patient recovered extraordinarily quickly after the operation, / but the surgeon still scheduled follow-up visits / to monitor healing.','副词，加强程度，表示异常地、非常地；不等于“绝对”或“毫无风险”。','恢复速度远超常见情况，因此用 extraordinarily 描述。'],['The patient recovered extraordinarily slowly, completing the full treatment in half the usual time with no delay.','The patient recovered extraordinarily quickly, completing the full treatment in half the usual time with no delay.','用时不到常规的一半且没有延误，说明恢复特别快，不是慢。'],[[1,'If a result is extraordinarily high, it is?',['far above what is ordinary','exactly average','necessarily false'],0,'extraordinarily 表示程度远超寻常。'],[1,'Which sentence uses extraordinarily naturally?',['The archive is extraordinarily well preserved.','The archive extraordinarily on Tuesday.','Extraordinarily the archive is it.'],0,'副词可加强 well preserved 的程度。'],[1,'“She was extraordinarily patient” suggests she was?',['remarkably patient','slightly impatient','exactly average in patience'],0,'extraordinarily 加强 patient，表示格外有耐心。'],[1,'Does extraordinarily always mean “impossibly”?',['No; it means unusually or exceptionally.','Yes; it means logically impossible.','No; it means exactly ordinary.'],0,'该词表达异常或非凡程度，不等于不可能。']]);
P('extrapolate','由 extra-“之外”与 interpolate 类推构成，统计中指把已知模式推及观测数据范围之外。',[1,'流行病学','Because testing covered only three regions, the researchers warned readers not to extrapolate the infection rate to the entire country.','由于检测只覆盖三个地区，研究人员提醒读者不要把感染率外推到全国。','Because testing covered only three regions, / the researchers warned readers not to extrapolate the infection rate / to the entire country.','及物动词；常用 extrapolate a trend/result from data to a wider population；外推需说明假设和不确定性。','从少数地区推断全国情况属于 extrapolate，且研究人员提醒谨慎。'],['The researcher extrapolated the future values by reporting only the measurements already observed and making no projection beyond them.','The researcher reported the measurements already observed without projecting beyond them.','仅复述已观察数值且不作范围外预测，不属于 extrapolation。'],[[1,'To extrapolate a trend is to?',['project it beyond the data already observed','delete every observation','repeat the same measurement without inference'],0,'extrapolate 是把已知模式推至数据范围之外。'],[1,'Why can extrapolation be risky?',['the pattern may not continue beyond the observed range','all data are always false','it changes the original observations'],0,'样本范围外的规律可能改变，因此外推有不确定性。'],[1,'A researcher extrapolates a local result to a whole country by?',['extending the observed pattern to a broader population','reporting only the local measurements','replacing the data with a guess unrelated to it'],0,'把局部模式延伸到更大范围即外推。'],[1,'Choose the natural construction.',['extrapolate from the sample to the population','extrapolate under the sample by the population','extrapolate at data without a pattern'],0,'常见搭配 extrapolate from A to B。']]);
P('extrapolation','由 extrapolate 加 -ion 构成，指将已知数据序列或模式延伸后得到的估算结论。',[1,'商业预测','The sales forecast was an extrapolation from two unusually strong quarters, so the finance team presented it as a scenario rather than a guarantee.','这份销售预测是从两个异常强劲季度外推得出的，因此财务团队把它作为一种情景，而非保证。','The sales forecast was an extrapolation from two unusually strong quarters, / so the finance team presented it as a scenario / rather than a guarantee.','名词；常接 from 已知数据，强调把趋势延伸到观测范围外所得结论，需保留不确定性。','基于两个季度推算未来，是 extrapolation 而非直接观察到的结果。'],['The five-year projection was a direct measurement because every future month had already been observed and recorded.','The five-year projection was an extrapolation because it extended recent observations into the future.','未来数据尚未观察到，依靠已知趋势预测应是外推而非直接测量。'],[[1,'An extrapolation is?',['an estimate obtained by extending a known pattern','a measurement directly observed at every future date','a list of unrelated facts'],0,'extrapolation 是延伸已知模式得到的推断。'],[1,'A report should label an extrapolation because?',['the pattern outside observed data may not hold','it is always guaranteed to be exact','it contains no assumptions'],0,'外推到观察范围之外具有不确定性。'],[1,'Which is an extrapolation?',['estimating next year’s demand from recent growth','counting last month’s actual orders','copying a receipt into a ledger'],0,'根据近期增长估计未来需求是外推。'],[1,'Choose the natural phrase.',['an extrapolation from the available data','extrapolation to observe last year directly','extrapolation at unrelated evidence'],0,'常用 extrapolation from + 数据。']]);
P('extraterrestrial','由 extra-“外部”与 terrestrial“地球的”组合而成，表示来自地球及其大气层之外。',[1,'天文学','The probe detected no extraterrestrial microbes, but its instruments found chemical traces that scientists will test again on Earth.','探测器没有发现地外微生物，但仪器检测到一些化学痕迹，科学家将带回地球再次检验。','The probe detected no extraterrestrial microbes, / but its instruments found chemical traces / that scientists will test again on Earth.','形容词或名词；科学语境中指地球之外的生命、物质或来源；迹象本身不等于证实外星生命。','研究对象若来自地球及大气层之外，才称 extraterrestrial。'],['A rock formed on Earth in a local volcano was called extraterrestrial even though it never left the planet.','A rock formed on Earth in a local volcano was called terrestrial because it originated on this planet.','地球内形成的岩石来源于本星球，应称 terrestrial。'],[[1,'Extraterrestrial life would be life?',['originating beyond Earth','living only under the ocean on Earth','created by a terrestrial plant'],0,'extraterrestrial 指来自地球之外。'],[1,'A meteorite may be described as extraterrestrial because it?',['originated beyond Earth before reaching it','was mined from a local mountain','was manufactured in a laboratory on Earth'],0,'陨石在抵达地球前来自地外。'],[1,'Does a chemical trace prove extraterrestrial life by itself?',['No; it needs further testing and evidence.','Yes; every trace is a living organism.','Yes; no alternative explanation is possible.'],0,'地外来源的迹象并不自动证明生命存在。'],[1,'The prefix extra- in extraterrestrial means?',['outside or beyond','inside','beneath'],0,'extra- 表示超出、在外部。']]);
P('extravagance','由 extravagant 加 -ance 构成；源头有拉丁语 extravagari“偏离常规”，现指超出合理限度的挥霍或行为。',[1,'家庭预算','The family postponed the luxury renovation because its extravagance would have consumed the emergency fund reserved for medical bills.','这家人推迟了奢华装修，因为这笔挥霍性开支会耗掉预留给医疗账单的应急金。','The family postponed the luxury renovation / because its extravagance would have consumed the emergency fund / reserved for medical bills.','不可数性质名词；常指花费或行为过度、不合常理，语气带批评。','装修支出会耗尽应急储蓄，超过合理预算，体现 extravagance。'],['The renovation was called an extravagance even though it cost nothing, used only donated materials, and preserved the emergency fund.','The renovation was called a sensible improvement because it cost nothing and preserved the emergency fund.','没有花费且不影响储蓄的项目不能因挥霍而称 extravagance。'],[[1,'An extravagance is?',['spending or behaviour beyond what is reasonable','a necessary low-cost repair','a carefully balanced budget'],0,'extravagance 指奢侈、过度花费或行为。'],[1,'Which purchase is most likely an extravagance?',['a costly third sports car bought despite unpaid rent','a basic coat needed for winter','medicine prescribed for an urgent illness'],0,'在拖欠房租时购入昂贵的第三辆跑车显得过度。'],[1,'The word extravagance often carries?',['a critical sense of excess','a guarantee of practicality','a meaning of careful saving'],0,'该词常带有超支或过度的批评意味。'],[1,'Choose the natural phrase.',['an unnecessary extravagance','extravagance at to pay','extravagance walked quickly'],0,'unnecessary extravagance 是自然搭配。']]);
P('extravagantly','由 extravagant 加副词后缀 -ly 构成，表示花费或行为远超合理程度。',[1,'慈善晚宴','The charity did not spend extravagantly on the venue; it chose a modest hall so that more of each donation could fund meals.','慈善机构没有在场地上铺张花费，而是选择朴素礼堂，让更多捐款用于餐食。','The charity did not spend extravagantly on the venue; / it chose a modest hall / so that more of each donation could fund meals.','副词，修饰 spend、dress、praise 等行为；强调过度、奢华或夸张。','选择简朴场地以保留捐款，说明没有挥霍。'],['The committee spent extravagantly by choosing the cheapest free room and refusing every optional purchase.','The committee spent economically by choosing the cheapest free room and refusing every optional purchase.','选免费场地且拒绝额外采购是节省开支，不是挥霍。'],[[1,'To spend extravagantly is to spend?',['far more than is reasonable','only what is strictly necessary','nothing at all'],0,'extravagantly 表示挥霍地、过分地。'],[1,'Which behaviour is extravagant?',['buying costly decorations beyond the event budget','borrowing a chair instead of buying one','repairing an item already owned'],0,'超出预算购买昂贵装饰体现过度花费。'],[1,'Choose the natural sentence.',['He dressed extravagantly for the ceremony.','He extravagantly the ceremony yesterday.','He dressed extravagantly at to ceremony.'],0,'副词可修饰 dressed，说明穿着奢华。'],[1,'If a company advertises extravagantly, it likely advertises?',['in a showy or excessive way','with no publicity whatsoever','only by correcting invoices'],0,'副词也可描述夸张铺张的行为方式。']]);
P('extricate','源自拉丁语 extricare“解开、脱身”，经法语进入英语，表示把人或物从困境、陷阱或残骸中救出。',[1,'救援','Firefighters worked for an hour to extricate the driver from the crushed cab while another team stabilised the vehicle.','消防员花了一小时把司机从压坏的驾驶室中救出，另一组人员同时固定车辆。','Firefighters worked for an hour to extricate the driver / from the crushed cab / while another team stabilised the vehicle.','及物动词，常见 extricate someone/something from a trap、wreck 或 difficulty。','把困在变形驾驶室中的司机救出，符合 extricate。'],['The rescue crew extricated the hiker from the ravine by pushing him farther down and blocking the only exit.','The rescue crew trapped the hiker in the ravine by pushing him farther down and blocking the only exit.','把人推得更深并堵住出口是困住而非救出。'],[[1,'To extricate someone from wreckage is to?',['free or remove them from it','push them deeper into it','leave them without assistance'],0,'extricate 表示使人脱离困境或残骸。'],[1,'Which phrase is standard?',['extricate herself from a difficult contract','extricate at a difficult contract','extricate to the contract'],0,'常用 extricate someone from something。'],[1,'A company tries to extricate itself from debt by?',['taking steps to escape the difficult financial position','borrowing more without a repayment plan','hiding all accounts from auditors'],0,'比喻义指摆脱困难处境。'],[1,'Choose the closest meaning: “They extricated the cable from the gears.”',['They freed it from being caught.','They attached it more firmly.','They cut it into smaller pieces.'],0,'从齿轮中解出电缆是使其脱离纠缠。']]);
P('extrinsic','由 extra-“外部”与 -ic 构成，表示并非事物内在固有、而是由外部提供或施加的。',[1,'学习动机','The study separated intrinsic interest from extrinsic rewards, such as cash bonuses offered for completing each optional lesson.','研究把内在兴趣与外在奖励区分开来，例如完成每节选修课后发放的现金奖金。','The study separated intrinsic interest from extrinsic rewards, / such as cash bonuses / offered for completing each optional lesson.','形容词；常搭配 extrinsic factor、motivation、value；与 intrinsic“内在的”相对。','现金奖金来自学习者之外，是 extrinsic reward。'],['The researchers called curiosity an extrinsic motive even though it came from the learner’s own interest and required no outside reward.','The researchers called curiosity an intrinsic motive because it came from the learner’s own interest.','来自个人内部兴趣的动机是 intrinsic，而非 extrinsic。'],[[1,'An extrinsic reward comes from?',['outside the activity or person itself','the inherent pleasure of doing the activity','a property that cannot be influenced by anything'],0,'extrinsic 指外部提供的，而非内在产生。'],[1,'Which is an extrinsic reason to study?',['a cash prize offered for a high score','curiosity about the subject','enjoyment of solving the problems'],0,'现金奖励来自外部，属于外在动机。'],[1,'Extrinsic most directly contrasts with?',['intrinsic','external','additional'],0,'intrinsic 表示内在的，与 extrinsic 相对。'],[1,'An extrinsic factor in a chemical process is?',['a condition supplied from outside the process','a property inherent in the substance','the final product itself in every case'],0,'外部施加的条件是 extrinsic factor。']]);
P('extrude','源自拉丁语 extrudere“向外推”，经法语进入英语；制造中指把材料强行通过模具挤压成型。',[1,'塑料加工','The factory extrudes molten polymer through a narrow die, producing a continuous tube that is cooled and cut to length.','工厂把熔融聚合物挤过狭窄模具，制成连续管材，再冷却并切成定长。','The factory extrudes molten polymer through a narrow die, / producing a continuous tube / that is cooled and cut to length.','及物动词；常以 plastic、metal、dough 等材料为宾语，模具决定截面形状。','材料经模具挤成连续管材，体现 extrude。'],['The machine extruded the polymer by pulling a finished pipe backward without forcing material through a shaping die.','The machine reeled in the finished pipe by pulling it backward without reshaping the polymer.','没有把材料压过模具成型就不是挤出；此处是回卷已成型管材。'],[[1,'To extrude plastic is to?',['force it through a shaped opening to form it','paint it after shaping','weigh it without changing its form'],0,'extrude 指将材料压过模具挤出成型。'],[1,'What helps determine the cross-section of extruded material?',['the shape of the die','the colour of the factory wall','the weight of the operator'],0,'模具开口形状决定挤出截面。'],[1,'Which process is extrusion?',['pressing dough through a patterned nozzle','cutting a finished loaf into slices','freezing water in a tray'],0,'面团被挤过有形状的喷嘴，属于挤出。'],[1,'Choose the natural construction.',['extrude aluminium through a die','extrude at aluminium into the die','extrude aluminium for yesterday'],0,'常说 extrude material through a die。']]);
P('extrusion','由 extrude 加 -ion 构成，指材料被挤出或挤压成型的过程，也可指挤出的材料。',[1,'食品制造','During extrusion, the dough passed through a shaped nozzle, giving every pasta strand the same ridged cross-section.','挤出成型时，面团穿过有形状的喷嘴，使每根意大利面条都具有相同的凹槽截面。','During extrusion, the dough passed through a shaped nozzle, / giving every pasta strand / the same ridged cross-section.','名词；可指制造过程或挤出的成品；材料通常被迫通过模具或喷嘴。','面团通过成形喷嘴的制造步骤是 extrusion。'],['The pasta’s extrusion occurred when finished strands were merely placed on a plate and no material passed through a nozzle.','The pasta’s plating occurred when finished strands were placed on a plate and no material passed through a nozzle.','把成品摆上盘子不是材料挤出成型。'],[[1,'Extrusion in manufacturing is?',['forcing material through a shaped opening','decorating a finished product by hand','measuring its colour'],0,'extrusion 指通过模具挤压成型的过程。'],[1,'Which object may be an extrusion?',['a continuous plastic profile pushed through a die','a lump of metal left untouched in storage','a printed label attached to a package'],0,'挤出的连续塑料型材是 extrusion 的成品义。'],[1,'The extrusion process can produce?',['a consistent cross-section along a long product','only irregular pieces broken at random','a verbal explanation of a recipe'],0,'连续挤压通常产生截面一致的长材。'],[1,'Choose the related verb.',['extrude','exult','examine'],0,'extrusion 是 extrude 的名词形式。']]);
P('extrusive','由 extrude 加形容词后缀 -ive 构成，地质学中指熔岩在地表喷出并冷却形成的岩石。',[1,'地质学','The geologist identified the dark basalt as extrusive rock because it cooled rapidly after lava reached the surface.','地质学家鉴定这块深色玄武岩为喷出岩，因为熔岩到达地表后迅速冷却。','The geologist identified the dark basalt as extrusive rock / because it cooled rapidly / after lava reached the surface.','地质学形容词，常修饰 igneous rock；与 underground cooling 的 intrusive 相对。','熔岩在地表冷却成玄武岩，符合 extrusive。'],['The geologist called the granite extrusive because it cooled slowly deep underground without reaching the surface.','The geologist called the granite intrusive because it cooled slowly deep underground.','地下缓慢冷却形成侵入岩 intrusive，不是地表喷出岩 extrusive。'],[[1,'Extrusive igneous rock forms when lava?',['reaches the surface and cools','remains molten deep underground for centuries','evaporates before solidifying'],0,'extrusive 指熔岩在地表喷出后冷却形成。'],[1,'Which rock is more likely extrusive?',['basalt formed from a surface lava flow','granite crystallised slowly deep underground','limestone formed from marine shells'],0,'玄武岩常由地表熔岩快速冷却形成。'],[1,'Extrusive contrasts with intrusive in the location of?',['cooling and solidification','the rock’s ownership','the date it is named'],0,'喷出与侵入的区别在于岩浆冷却位置。'],[1,'Choose the natural phrase.',['extrusive volcanic rock','extrusive under the ground slowly','extrusive at the mineral'],0,'extrusive 可修饰 volcanic rock。']]);
P('exuberant','源于拉丁语 exuberare“丰盛、生长旺盛”，经法语进入英语；可形容欢快精力充沛，也可指植物繁茂。',[1,'庆祝活动','The children gave an exuberant welcome to the returning coach, cheering and waving handmade signs across the gym.','孩子们在体育馆里欢呼并挥舞手制标语，热情洋溢地欢迎归来的教练。','The children gave an exuberant welcome / to the returning coach, / cheering and waving handmade signs across the gym.','s1 指欢快而充满活力；s2 指植物生长茂盛。可根据人或植被等主语区分。','孩子们欢呼挥手表现出欢乐旺盛的活力，体现 s1。'],['The exuberant garden was barren, with every plant dead and no growth visible anywhere.','The desolate garden was barren, with every plant dead and no growth visible anywhere.','寸草不生与植物繁茂的 exuberant 相反，desolate 更准确。'],[[1,'An exuberant crowd is?',['cheerful and full of energy','quiet, exhausted, and motionless','made entirely of plants'],0,'exuberant s1 描写欢乐而有活力的人群。'],[2,'Exuberant vegetation grows?',['thickly and healthily','not at all','only as dry dust'],0,'s2 描述植物茂盛生长。'],[1,'Which greeting is exuberant?',['people cheer loudly and wave as a friend arrives','people remain silent and turn away','people record the time without reacting'],0,'热烈欢呼是 exuberant 的情绪表现。'],[2,'After rain, the hillside is exuberant with?',['lush grasses and new growth','bare soil and dead stems','concrete foundations only'],0,'郁郁葱葱的新生长对应植物义。']]);
P('exude','源自拉丁语 exsudare“渗汗、渗出”，经法语进入英语；可指液体慢慢渗出，也可指气质显露或气味弥漫。',[1,'植物学','Clear resin began to exude from the pine wound after the branch was cut, forming a sticky bead along the edge of the bark.','松枝被切断后，透明树脂开始从伤口渗出，在树皮边缘形成黏稠液珠。','Clear resin began to exude from the pine wound / after the branch was cut, / forming a sticky bead along the edge of the bark.','及物或不及物均可；s1 渗出液体，s2 显露特质，s3 气味等从来源处弥漫。','树脂从切口缓慢流出，体现 exude 的 s1。'],['The cut pine exuded confidence from its trunk in clear, sticky drops.','The cut pine exuded clear resin from its trunk in sticky drops.','树木从切口渗出的是树脂等液体，不是人类的信心。'],[[1,'Sap exudes from a cut branch when it?',['slowly flows out of the wound','is pushed back into the roots','turns immediately into wood'],0,'exude s1 指液体从表面或伤口渗出。'],[2,'A leader who exudes confidence?',['shows confidence clearly through manner','hides all signs of confidence','measures confidence in a bottle'],0,'exude s2 表示鲜明地流露某种特质。'],[3,'A strong scent exudes from a flower when it?',['spreads slowly into the surrounding air','is sealed inside a jar forever','is converted into a written list'],0,'气味从来源处向周围空气弥漫是 s3。'],[1,'Which construction is natural?',['The wound exuded clear fluid.','The wound exuded at clear fluid.','The wound exuded to the fluid.'],0,'exude 可直接接渗出的液体作宾语。']]);
P('exultant','由拉丁语 exsultare“欢跃、欣喜”进入英语，形容因成功或胜利而极度欢欣、充满胜利喜悦。',[1,'体育赛场','The exultant captain lifted the trophy after the final whistle, smiling as teammates rushed over to celebrate their comeback victory.','终场哨响后，队长欣喜若狂地举起奖杯；队友冲上来庆祝这场逆转胜利。','The exultant captain lifted the trophy / after the final whistle, / smiling as teammates rushed over to celebrate their comeback victory.','形容词；s1 强调成功后的欢欣，s2 带有胜利后的自豪与得意，语义接近。','逆转获胜后举杯庆祝体现胜利后的欢欣。'],['After losing the final by a wide margin, the runner felt exultant and mourned the defeat.','The dejected runner looked defeated and mournful after losing the final by a wide margin.','大比分失利后的沮丧与 exultant 的欢欣相反。'],[[1,'An exultant winner feels?',['great joy after succeeding','deep sorrow after failing','no emotion at all'],0,'exultant s1 指成功后的欣喜。'],[2,'An exultant team after a final is especially?',['triumphant and proud of its victory','confused about whether it competed','ashamed of having won'],0,'s2 突出胜利后的自豪感。'],[1,'Which moment is exultant?',['a crew cheers when its rescue mission succeeds','a crew mourns after losing its boat','a crew waits silently before learning the result'],0,'任务成功后的欢呼是胜利欣喜。'],[2,'Choose the closest word for a triumphant, proud reaction.',['exultant','indifferent','despondent'],0,'exultant 可表示胜利后充满自豪和喜悦。']]);
P('eye-catching','由 eye 与 catch 组成的复合形容词，字面为“抓住目光”，指颜色或设计醒目、能吸引注意。',[1,'平面设计','The designer used one eye-catching orange panel on the museum poster so visitors would notice the date without missing the quiet layout.','设计师在博物馆海报上使用一块醒目的橙色面板，让参观者注意到日期，同时不破坏整体简洁感。','The designer used one eye-catching orange panel / on the museum poster / so visitors would notice the date without missing the quiet layout.','形容词，常修饰 colour、display、design、headline；指视觉醒目，不自动表示品质优秀。','橙色面板吸引视线并凸显日期，符合 eye-catching。'],['The grey sign was eye-catching because it blended invisibly into the wall and every passer-by overlooked it.','The grey sign was inconspicuous because it blended into the wall and every passer-by overlooked it.','与墙面融为一体且被忽略说明不醒目，应为 inconspicuous。'],[[1,'An eye-catching display is designed to?',['attract people’s attention','remain unnoticed','block all information from view'],0,'eye-catching 意为醒目、能抓住注意力。'],[1,'Which feature is most eye-catching on a crowded shelf?',['a bright, distinctive package','a plain label identical to every neighbour','a product hidden behind a box'],0,'色彩醒目且有辨识度的包装容易吸引目光。'],[1,'Does eye-catching necessarily mean “well made”?',['No; it describes drawing the eye.','Yes; it guarantees high quality.','No; it means invisible.'],0,'该词说明视觉显眼，不评价质量好坏。'],[1,'Choose the natural phrase.',['an eye-catching headline','an eye-catching quietly','eye-catching under to arrive'],0,'eye-catching 可修饰 headline。']]);
P('eye-opening','由 eye 与 opening 组成的复合形容词，表示揭示新事实、改变原有看法或令人惊讶的。',[1,'教育经历','Volunteering at the shelter was eye-opening for the students, who learned how housing insecurity affects families beyond the statistics.','在收容中心做志愿者让学生大开眼界，他们了解到住房不稳定如何影响统计数字背后的家庭。','Volunteering at the shelter was eye-opening for the students, / who learned how housing insecurity affects families / beyond the statistics.','形容词；常修饰 experience、report、visit；强调带来新认识，不等于仅仅有趣。','学生通过亲历获得统计数字之外的新认识，体现 eye-opening。'],['The report was eye-opening because it repeated only facts the readers already knew and changed no one’s understanding.','The report was familiar because it repeated facts the readers already knew and changed no one’s understanding.','没有提供新认识的报告并不令人开眼界。'],[[1,'An eye-opening experience?',['reveals something surprising or previously unnoticed','confirms every assumption without new information','is seen only with the eyes'],0,'eye-opening 指揭示新情况、令人改变认识。'],[1,'Which report is eye-opening?',['one that reveals an overlooked safety risk','one that repeats the same known figures','one whose pages are blank'],0,'揭示被忽视风险带来新认识。'],[1,'Eye-opening is closest in meaning to?',['surprising and informative','visually invisible','certainly false'],0,'该词通常表示令人惊讶并增长认识。'],[1,'Choose the natural phrase.',['an eye-opening discovery','eye-opening to sleep softly','an eye-opening yesterday'],0,'eye-opening 可修饰 discovery。']]);
P('eyeball','由 eye 与 ball 组成的复合名词，指位于眼眶内的球状视觉器官。',[1,'解剖学','The ophthalmologist examined the eyeball for pressure changes before checking the retina and optic nerve.','眼科医生先检查眼球压力变化，再查看视网膜和视神经。','The ophthalmologist examined the eyeball for pressure changes / before checking the retina / and optic nerve.','可数名词；指眼眶内的球状器官本身，不等同整个视觉系统。','测量眼压并检查视网膜前的器官是眼球。'],['The optician called the lens outside the face an eyeball, although the eyeball itself sits within the eye socket.','The optician called the globe within the eye socket the eyeball.','眼镜片在眼球外部；眼球是位于眼眶内的球状器官。'],[[1,'The eyeball is?',['the ball-shaped organ of sight in the socket','the transparent lens worn over the eye','the bone forming the jaw'],0,'eyeball 指眼眶内的球状视觉器官。'],[1,'Which structure is part of the eyeball?',['the globe containing the retina','a spectacle frame resting on the nose','the outer ear canal'],0,'视网膜位于眼球内。'],[1,'An ophthalmologist may examine the eyeball to assess?',['eye health and pressure','hearing range','the strength of a knee joint'],0,'眼科检查关注眼球及其内部结构。'],[1,'Choose the natural phrase.',['the white of the eyeball','eyeball at the foot','eyeball to a calendar'],0,'the white of the eyeball 是自然说法。']]);
P('eyewitness','由 eye 与 witness 组成的复合词，指亲眼看见事件发生的人；也可指在法庭陈述所见的证人。',[2,'法庭审理','An eyewitness testified that she saw the cyclist enter the junction before the signal changed, and the lawyers questioned her view of the traffic lights.','一名目击证人作证说，她看到骑车人先进入路口、随后信号才变化；律师就她观察信号灯的视角进行了询问。','An eyewitness testified that she saw the cyclist enter the junction / before the signal changed, / and the lawyers questioned her view of the traffic lights.','可数名词；s1 强调亲眼目睹事件，s2 在法庭语境中强调就所见提供证词。','该目击者在庭上就自己所见作证，符合 s2。'],['The eyewitness testified about the crash despite arriving after the road had been cleared and seeing nothing happen.','The later-arriving witness described the scene but was not an eyewitness to the crash itself.','事发后才到场的人没有亲眼看见碰撞，不是该事件的 eyewitness。'],[[1,'An eyewitness to a collision is someone who?',['saw the collision happen','heard about it days later','read about it in a newspaper'],0,'s1 指亲眼看到事件发生的人。'],[2,'In court, an eyewitness gives evidence about?',['what they personally saw','what a stranger guessed','what they hope happened'],0,'法庭中的 eyewitness 就亲眼所见提供证词。'],[1,'Which person is an eyewitness to a fire?',['a passer-by who watched it start','a reporter who arrived after it was extinguished','a reader who saw a photo later'],0,'亲眼看到火灾开始的人是目击者。'],[2,'Why might lawyers question an eyewitness?',['to test what the witness actually saw and remembered','to ask the witness to invent evidence','to determine the witness’s shoe size only'],0,'庭审会核实证人的观察与记忆。']]);
P('fabrication','由 fabricate 加 -ion 构成；fabricate 经拉丁语 fabricare“制作、建造”进入英语，现代既可指制造，也可指捏造事实。',[1,'新闻核查','The reporter exposed the quotation as a fabrication after checking the recording and finding that the speaker had never made the statement.','记者核对录音后揭穿这段引语是捏造的，因为发言者从未说过这句话。','The reporter exposed the quotation as a fabrication / after checking the recording / and finding that the speaker had never made the statement.','s1 指把虚假说法伪装成事实；s2 指用材料或零件制造物品。','录音证明引语从未说出，故其是虚构捏造 s1。'],['The newspaper confirmed the quotation as a fabrication because the unedited recording clearly contained the speaker’s exact words.','The newspaper confirmed the quotation as authentic because the unedited recording clearly contained the speaker’s exact words.','原始录音能证实引语真实，不是编造。'],[[1,'A fabrication presented as news is?',['a false account made to seem true','a verified quotation from a recording','a neutral list of dates'],0,'fabrication s1 指捏造的事实或说法。'],[2,'Metal fabrication refers to?',['making products from metal parts or material','inventing a false rumour','testing whether a witness remembers an event'],0,'fabrication s2 指制造、加工材料。'],[1,'Which is a fabrication?',['an invented invoice falsely claimed to be genuine','a receipt verified by the shop’s records','a forecast clearly labelled as uncertain'],0,'伪造并冒充真实的账单是 fabrication。'],[2,'A workshop specialising in fabrication may?',['cut and assemble metal components','spread an invented story','serve a court summons'],0,'金属加工车间从事材料制造。']]);
P('facelift','由 face 与 lift 组成的复合词，现代常指不彻底重建而让建筑、产品或地区显得更新的翻新。',[1,'城市更新','The old market received a facelift with repaired shopfronts, fresh paint, and safer lighting, while its historic structure remained intact.','老市场通过修整店面、重新粉刷和改善照明焕然一新，同时保留了历史结构。','The old market received a facelift / with repaired shopfronts, fresh paint, and safer lighting, / while its historic structure remained intact.','可数名词；常用于 building、website、brand、neighbourhood；通常是表面或局部更新，不是全部重建。','市场结构仍在，只更新外观与设施，符合 facelift。'],['The market’s facelift demolished every historic building and replaced the entire district with a new complex.','The market’s complete redevelopment demolished every historic building and replaced the entire district with a new complex.','整个地区拆除重建是 complete redevelopment，不是保留主体的 facelift。'],[[1,'A website facelift usually means?',['updating its appearance without rebuilding everything','deleting the internet','moving the company to a new country'],0,'facelift 常指保留主体而更新外观。'],[1,'Which is a facelift for a public square?',['new paving and lighting while keeping its layout','demolishing the whole neighbourhood','changing the weather above it'],0,'改善铺装灯光而保留整体是翻新。'],[1,'Does a facelift normally require total reconstruction?',['No; it often refreshes an existing structure.','Yes; every original part must be destroyed.','Yes; it refers only to moving furniture.'],0,'facelift 与全部重建不同，常为局部更新。'],[1,'Choose the natural phrase.',['give the station a facelift','facelift to the station by arriving','facelift on yesterday quickly'],0,'give something a facelift 是常用搭配。']]);
P('facetious','源自拉丁语 facetia“诙谐、玩笑”，经法语进入英语；指在严肃场合开不合时宜的玩笑或故作滑稽。',[1,'工作沟通','When the engineer asked whether the cracked beam was safe, Marco made a facetious remark about “testing it with a heavier truck,” upsetting the inspection team.','工程师询问裂梁是否安全时，马尔科开了句不合时宜的玩笑，说要“用更重的卡车来测试”，惹恼了检查组。','When the engineer asked whether the cracked beam was safe, / Marco made a facetious remark / about “testing it with a heavier truck,” upsetting the inspection team.','形容词，常搭配 remark、comment、tone；玩笑涉及严肃问题时可能令人恼火。','用更重卡车测试裂梁的玩笑轻慢安全隐患，符合 facetious。'],['The engineer’s facetious response was a detailed safety analysis with measurements, load limits, and a serious risk assessment.','The engineer’s thorough response was a detailed safety analysis with measurements, load limits, and a serious risk assessment.','严肃详尽的安全分析不是开玩笑的 facetious response。'],[[1,'A facetious comment is?',['a joke that may be ill-timed or inappropriate','a formal measurement taken with a ruler','a fully verified safety report'],0,'facetious 常指不合时宜的玩笑。'],[1,'Which remark is facetious in a safety meeting?',['“Let’s test the damaged bridge by driving a tank over it.”','“The measured crack is twelve millimetres long.”','“The bridge must remain closed until inspection.”'],0,'拿危险测试开玩笑显得轻率、不合时宜。'],[1,'Facetious is not always a compliment because the speaker may seem?',['insensitive to a serious topic','carefully factual','unable to make any sound'],0,'严肃话题上玩笑可能显得不够体谅。'],[1,'Choose the natural phrase.',['a facetious remark','facetious at the meetingly','a facetious measure of length'],0,'facetious 可修饰 remark。']]);
P('facial','由 face 加形容词后缀 -ial 构成，可表示与面部有关、面部护理，或面部表情方面。',[3,'情绪识别','The interviewer noticed a brief facial expression of relief when the applicant heard that the travel grant had been approved.','听到差旅资助获批时，面试官注意到申请人脸上短暂流露出一丝宽慰。','The interviewer noticed a brief facial expression of relief / when the applicant heard / that the travel grant had been approved.','s1 为“面部的”；s2 作名词指面部护理；s3 表示面部表情相关的。','facial expression 修饰脸上流露出的情绪，体现 s3。'],['The spa advertised a facial treatment, meaning a facial expression used to show surprise.','The spa advertised a facial treatment, a beauty service that cleans and cares for the face.','facial 作名词时指面部护理，不是表情；后者应说 facial expression。'],[[1,'A facial injury affects?',['the face','the ankle','the weather'],0,'facial s1 表示面部相关。'],[2,'A spa facial is?',['a beauty treatment that cleans and cares for the face','a medical scan of the lungs','a person who witnessed a crime'],0,'facial s2 作名词指面部护理。'],[3,'Facial expressions can communicate?',['feelings shown on the face','the temperature inside a computer','a person’s family origin'],0,'facial s3 与面部表情相关。'],[3,'Which phrase uses facial to mean expression-related?',['facial muscles tighten with worry','a facial at the beauty clinic','a facial bone is fractured'],0,'facial muscles 与面部表情动作相关。']]);
P('facile','源自拉丁语 facilis“容易的”，经法语进入英语；现代常含贬义，指得出过于轻率、因而肤浅的结论。',[1,'批判性思维','Calling the housing crisis “a simple matter of personal choice” was a facile explanation that ignored rents, wages, and local policy.','把住房危机说成“个人选择的小事”是肤浅的解释，忽略了租金、工资和地方政策。','Calling the housing crisis “a simple matter of personal choice” / was a facile explanation / that ignored rents, wages, and local policy.','形容词，常修饰 answer、solution、argument；此义不是赞美“容易”，而是批评想得太简单。','解释忽略多项重要因素，因过分简单而肤浅，符合 facile。'],['The researcher’s facile conclusion carefully weighed the evidence, tested alternatives, and addressed every major limitation.','The researcher’s well-supported conclusion carefully weighed the evidence, tested alternatives, and addressed every major limitation.','充分权衡证据并回应局限并非过于轻率的结论；well-supported 更准确。'],[[1,'A facile answer to a complex question is often?',['too easy and shallow to deal with the real issues','carefully reasoned and complete','impossible to understand because it is technical'],0,'facile 常批评答案想得过于简单、肤浅。'],[1,'Which is a facile explanation of traffic congestion?',['“People are impatient,” with no analysis of roads or transit','a detailed study of road capacity and bus frequency','a report comparing several causes with evidence'],0,'仅归因于不耐烦而不分析结构因素过于轻率。'],[1,'In modern critical writing, facile usually has?',['a negative sense of oversimplification','a guaranteed positive sense of elegance','a literal meaning of facial'],0,'facile 常带有“过于简单”的贬义。'],[1,'Choose the natural phrase.',['a facile solution to a complex problem','facile to the solution quickly','a facile measured in centimetres'],0,'facile 可修饰 solution，并常含批评意味。']]);
P('facilitation','由 facilitate 加名词后缀 -ion 构成；facilitate 源自拉丁语 facilis“容易的”，表示帮助一项活动或协议更顺利进行。',[1,'团队协作','The facilitator used brief rounds and a shared agenda to support the facilitation of a meeting between residents and the planning office.','主持人通过简短轮流发言和共同议程，促进居民与规划办公室之间的会议顺利进行。','The facilitator used brief rounds and a shared agenda / to support the facilitation of a meeting / between residents and the planning office.','不可数名词；常用于会议、协商、学习过程，强调促成交流与推进活动，不是替参与者作决定。','主持人设计流程以帮助双方交流与会议推进，体现 facilitation。'],['The chair’s facilitation improved the meeting by silencing residents, hiding each proposal, and preventing agreement.','The chair’s facilitation improved the meeting by inviting residents to speak, clarifying proposals, and helping the group reach agreement.','压制发言和阻止共识与“帮助活动更顺利”相矛盾。'],[[1,'Facilitation of a meeting means?',['helping the meeting proceed more easily and productively','making every decision for the participants','canceling all discussion'],0,'facilitation 指帮助活动顺利进行。'],[1,'A neutral facilitator should usually?',['support discussion without imposing the outcome','choose a winner before anyone speaks','hide relevant information from participants'],0,'主持协商要推进讨论，而不替参与者决定结果。'],[1,'Which action improves facilitation?',['set a clear agenda and make room for each participant','allow one person to interrupt everyone','remove the topic from the meeting'],0,'清楚议程与平等发言能促进会议。'],[1,'Choose the natural phrase.',['facilitation of negotiations','facilitation at to negotiate','facilitation the agreement yesterdayly'],0,'facilitation of negotiations 是自然搭配。']]);

})();
